// ─── Software deployment handlers ───

/// One persisted `approved_packages` row (migration 032).
/// All enum columns are stored as TEXT in Postgres and reproduced as strings
/// in the JSON response, matching the engine's serde shape for PackageType /
/// SiteScope.
#[derive(sqlx::FromRow)]
struct ApprovedPackageRow {
    id: String,
    name: String,
    version: String,
    vendor: String,
    package_type: String,
    approved_by: String,
    approved_date: chrono::NaiveDate,
    site_scope: String,
    site_scope_list: Vec<String>,
}

impl ApprovedPackageRow {
    fn to_json(&self) -> Value {
        let scope: Value = if self.site_scope == "specific" {
            json!({"Specific": self.site_scope_list})
        } else {
            json!("All")
        };
        json!({
            "id": self.id,
            "name": self.name,
            "version": self.version,
            "vendor": self.vendor,
            "package_type": self.package_type,
            "approved_by": self.approved_by,
            "approved_date": self.approved_date.to_string(),
            "site_scope": scope,
            "source": "database",
        })
    }
}

const PACKAGE_COLUMNS: &str =
    "id, name, version, vendor, package_type, approved_by, approved_date, \
     site_scope, site_scope_list";

/// One persisted `software_deployments` row (migration 032). `plan_json` and
/// `evidence_json` are selected as text so they round-trip through `to_json`.
#[derive(sqlx::FromRow)]
struct SoftwareDeploymentRow {
    id: String,
    server_name: String,
    package_id: String,
    package_name: String,
    target_version: String,
    scheduled_time: Option<chrono::DateTime<chrono::Utc>>,
    requester: String,
    status: String,
    approved_by: Option<String>,
    plan_json: Option<String>,
    executed_at: Option<chrono::DateTime<chrono::Utc>>,
    verified_at: Option<chrono::DateTime<chrono::Utc>>,
    evidence_json: String,
}

impl SoftwareDeploymentRow {
    fn to_json(&self) -> Value {
        json!({
            "id": self.id,
            "server_name": self.server_name,
            "package_id": self.package_id,
            "package_name": self.package_name,
            "target_version": self.target_version,
            "scheduled_time": self.scheduled_time.as_ref().map(|t| t.to_rfc3339()),
            "requester": self.requester,
            "status": self.status,
            "approved_by": self.approved_by,
            "plan": self.plan_json.as_deref()
                .and_then(|s| serde_json::from_str::<Value>(s).ok())
                .unwrap_or(Value::Null),
            "executed_at": self.executed_at.as_ref().map(|t| t.to_rfc3339()),
            "verified_at": self.verified_at.as_ref().map(|t| t.to_rfc3339()),
            "evidence": self.evidence_json
                .parse::<Value>()
                .unwrap_or_else(|_| json!([])),
            "source": "database",
        })
    }
}

const DEPLOYMENT_COLUMNS: &str =
    "id, server_name, package_id, package_name, target_version, scheduled_time, \
     requester, status, approved_by, plan_json::text AS plan_json, executed_at, \
     verified_at, evidence_json::text AS evidence_json";

#[derive(Debug, Deserialize)]
struct SoftwarePackagesQuery {
    site: Option<String>,
}

#[derive(Debug, Deserialize)]
struct SoftwareComplianceQuery {
    site: String,
}

async fn software_packages_list(
    AuthExtractor(session): AuthExtractor,
    Query(query): Query<SoftwarePackagesQuery>,
) -> ApiResult {
    // #2: scoped-site read ("" = all sites for an unrestricted caller).
    let site_scoped = enforce_site_scope(&session, query.site.as_deref(), "")?;
    let site = site_scoped.as_str();
    if let Some(pool) = get_db() {
        // DB path: read approved_packages table (source of truth).
        // site_scope filter mirrors engine SiteScope::covers:
        //   scope='all'  → matches any site request
        //   scope='specific' → site_scope_list must contain the requested site
        // When no site filter is provided ($1 = '') all rows are returned.
        let rows: Vec<ApprovedPackageRow> = sqlx::query_as(&format!(
            "SELECT {PACKAGE_COLUMNS} FROM approved_packages \
             WHERE ($1 = '' \
                OR site_scope = 'all' \
                OR ($1 <> '' AND site_scope = 'specific' AND $1 = ANY(site_scope_list))) \
             ORDER BY id"
        ))
        .bind(site)
        .fetch_all(pool)
        .await
        .map_err(db_error)?;
        let packages: Vec<Value> = rows.iter().map(ApprovedPackageRow::to_json).collect();
        return Ok(Json(json!({
            "source": "database",
            "packages": packages,
            "count": packages.len(),
        })));
    }
    // No-DB: engine in-memory store (unchanged fallback).
    let site_opt = if site.is_empty() { None } else { Some(site) };
    let packages = software_deployment::get_approved_packages(site_opt);
    Ok(Json(serde_json::to_value(packages).unwrap()))
}

async fn software_validate(Json(body): Json<software_deployment::DeploymentRequest>) -> ApiResult {
    // DB path: check required fields inline, then query approved_packages to
    // validate the package_id exists. PACKAGE_STORE is not populated from DB rows
    // after restart, so calling validate_deployment() here would false-fail on
    // database-seeded packages.
    if let Some(pool) = get_db() {
        let mut errors: Vec<&str> = Vec::new();
        if body.server_name.is_empty() {
            errors.push("Server name is required");
        }
        if body.package_id.is_empty() {
            errors.push("Package ID is required");
        }
        if body.target_version.is_empty() {
            errors.push("Target version is required");
        }
        if body.requester.is_empty() {
            errors.push("Requester is required");
        }

        // Validate package_id against approved_packages table.
        let pkg_exists: bool = if body.package_id.is_empty() {
            false
        } else {
            sqlx::query_scalar::<_, bool>(
                "SELECT EXISTS(SELECT 1 FROM approved_packages WHERE id = $1)",
            )
            .bind(&body.package_id)
            .fetch_one(pool)
            .await
            .map_err(db_error)?
        };

        if !body.package_id.is_empty() && !pkg_exists {
            errors.push("Package is not in the approved catalog");
        }

        let mut warnings = vec!["DRY-RUN: Server online status verified (simulated)"];
        if body.scheduled_time.is_empty() {
            warnings.push("No scheduled time provided — deployment will be immediate (dry-run)");
        }

        return Ok(Json(json!({
            "passed": errors.is_empty(),
            "errors": errors,
            "warnings": warnings,
            "failed_rules": [],
            "remediation": [],
            "source": "database",
        })));
    }
    // No-DB fallback: engine validates against PACKAGE_STORE (current-process only).
    match software_deployment::validate_deployment(&body) {
        Ok(result) => Ok(Json(serde_json::to_value(result).unwrap())),
        Err(e) => Err(status_400(&e)),
    }
}

async fn software_plan(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<software_deployment::DeploymentRequest>,
) -> ApiResult {
    // Engine validates, generates ID, builds the plan struct (dry-run).
    let record = match software_deployment::plan_deployment(&body) {
        Ok(r) => r,
        Err(e) => return Err(status_400(&e)),
    };

    if let Some(pool) = get_db() {
        let plan_json = record
            .plan
            .as_ref()
            .and_then(|p| serde_json::to_string(p).ok());
        let scheduled: Option<chrono::DateTime<chrono::Utc>> = body
            .scheduled_time
            .parse::<chrono::DateTime<chrono::Utc>>()
            .ok();
        let mut tx = pool.begin().await.map_err(db_error)?;
        let row: SoftwareDeploymentRow = sqlx::query_as(&format!(
            "INSERT INTO software_deployments \
                (id, server_name, package_id, package_name, target_version, \
                 scheduled_time, requester, status, plan_json) \
             VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9::jsonb) \
             RETURNING {DEPLOYMENT_COLUMNS}"
        ))
        .bind(&record.id)
        .bind(&record.server_name)
        .bind(&record.package_id)
        .bind(&record.package_name)
        .bind(&record.target_version)
        .bind(scheduled)
        .bind(&record.requester)
        .bind("Planned")
        .bind(plan_json)
        .fetch_one(&mut *tx)
        .await
        .map_err(db_error)?;
        let deployment_id = row.id.clone();
        audit::record_audit_tx(
            &mut tx,
            &session,
            &audit::security_audit(
                "software-plan",
                None,
                "planned",
                json!({ "deployment_id": deployment_id }),
            ),
        )
        .await
        .map_err(db_error)?;
        tx.commit().await.map_err(db_error)?;
        return Ok(Json(row.to_json()));
    }
    Ok(Json(serde_json::to_value(record).unwrap()))
}

async fn software_approve(
    Path(id): Path<String>,
    Extension(session): Extension<AuthSession>,
) -> ApiResult {
    // The approver is the AUTHENTICATED caller (resolved by the auth middleware
    // and injected into request extensions), never a client-supplied body field.
    // Audit integrity requires attributing the approval to the real principal —
    // a caller must not be able to claim someone else (or "admin") approved.
    let approver = session.user_id;

    if let Some(pool) = get_db() {
        // DB path: validate inline against the DB row, then CAS UPDATE.
        // Do NOT call approve_deployment() here — it mutates DEPLOYMENT_STORE,
        // which is not populated from DB rows after a restart.
        let row: Option<SoftwareDeploymentRow> = sqlx::query_as(&format!(
            "UPDATE software_deployments \
             SET status = 'Approved', approved_by = $2, updated_at = NOW() \
             WHERE id = $1 AND status = 'Planned' \
             RETURNING {DEPLOYMENT_COLUMNS}"
        ))
        .bind(&id)
        .bind(&approver)
        .fetch_optional(pool)
        .await
        .map_err(db_error)?;
        return match row {
            Some(updated) => Ok(Json(updated.to_json())),
            None => {
                // Distinguish 404 from wrong-state 409.
                let exists: Option<(String,)> =
                    sqlx::query_as("SELECT status FROM software_deployments WHERE id = $1")
                        .bind(&id)
                        .fetch_optional(pool)
                        .await
                        .map_err(db_error)?;
                match exists {
                    None => Err(status_404(&id)),
                    Some((status,)) => Err(status_409(&format!(
                        "Deployment {} is in status '{}', expected 'Planned'",
                        id, status
                    ))),
                }
            }
        };
    }
    // No-DB fallback: engine validates + mutates in-memory store.
    match software_deployment::approve_deployment(&id, &approver) {
        Ok(record) => Ok(Json(serde_json::to_value(record).unwrap())),
        Err(e) => Err(status_400(&e)),
    }
}

async fn software_execute(Path(id): Path<String>) -> ApiResult {
    if let Some(pool) = get_db() {
        // DB path: do NOT call execute_deployment() — it requires the row in
        // DEPLOYMENT_STORE which is not populated from DB after restart.
        // Build a minimal evidence payload inline and CAS-update the row.
        let now = chrono::Utc::now();
        let evidence_json = serde_json::to_string(&serde_json::json!([{
            "step": "execute",
            "result": "success",
            "timestamp": now.to_rfc3339(),
            "source": "database",
        }]))
        .unwrap_or_else(|_| "[]".into());
        let row: Option<SoftwareDeploymentRow> = sqlx::query_as(&format!(
            "UPDATE software_deployments \
             SET status = 'Executed', executed_at = $2, \
                 evidence_json = $3::jsonb, updated_at = NOW() \
             WHERE id = $1 AND status = 'Approved' \
             RETURNING {DEPLOYMENT_COLUMNS}"
        ))
        .bind(&id)
        .bind(now)
        .bind(evidence_json)
        .fetch_optional(pool)
        .await
        .map_err(db_error)?;
        return match row {
            Some(updated) => Ok(Json(updated.to_json())),
            None => {
                let exists: Option<(String,)> =
                    sqlx::query_as("SELECT status FROM software_deployments WHERE id = $1")
                        .bind(&id)
                        .fetch_optional(pool)
                        .await
                        .map_err(db_error)?;
                match exists {
                    None => Err(status_404(&id)),
                    Some((status,)) => Err(status_409(&format!(
                        "Deployment {} is in status '{}', expected 'Approved'",
                        id, status
                    ))),
                }
            }
        };
    }
    // No-DB fallback: engine validates Approved→Executed and builds evidence.
    match software_deployment::execute_deployment(&id) {
        Ok(evidence) => Ok(Json(serde_json::to_value(evidence).unwrap())),
        Err(e) => Err(status_400(&e)),
    }
}

async fn software_verify(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> ApiResult {
    if let Some(pool) = get_db() {
        // DB path: do NOT call verify_deployment() — it requires the row in
        // DEPLOYMENT_STORE which is not populated from DB after restart.
        // CAS-update the row; handle None by checking current state.
        let now = chrono::Utc::now();
        let mut tx = pool.begin().await.map_err(db_error)?;
        let row: Option<SoftwareDeploymentRow> = sqlx::query_as(&format!(
            "UPDATE software_deployments \
             SET status = 'Verified', verified_at = $2, updated_at = NOW() \
             WHERE id = $1 AND status = 'Executed' \
             RETURNING {DEPLOYMENT_COLUMNS}"
        ))
        .bind(&id)
        .bind(now)
        .fetch_optional(&mut *tx)
        .await
        .map_err(db_error)?;

        return match row {
            Some(updated) => {
                audit::record_audit_tx(
                    &mut tx,
                    &session,
                    &audit::security_audit(
                        "software-verify",
                        None,
                        "verified",
                        json!({ "deployment_id": &id }),
                    ),
                )
                .await
                .map_err(db_error)?;
                tx.commit().await.map_err(db_error)?;
                Ok(Json(json!({
                    "passed": true,
                    "status": "Verified",
                    "deployment": updated.to_json(),
                    "source": "database",
                })))
            }
            None => {
                // tx drops here (rollback) — no mutation happened
                // Idempotent: already Verified → 200.
                // Wrong state (incl. Completed) or missing → 409/404.
                let exists: Option<(String,)> =
                    sqlx::query_as("SELECT status FROM software_deployments WHERE id = $1")
                        .bind(&id)
                        .fetch_optional(pool)
                        .await
                        .map_err(db_error)?;
                match exists {
                    None => Err(status_404(&id)),
                    Some((ref s,)) if s == "Verified" => Ok(Json(json!({
                        "passed": true,
                        "status": s,
                        "note": "already verified",
                        "source": "database",
                    }))),
                    Some((status,)) => Err(status_409(&format!(
                        "Deployment {} is in status '{}', expected 'Executed'",
                        id, status
                    ))),
                }
            }
        };
    }
    // No-DB fallback: engine validates Executed→Verified and returns result.
    match software_deployment::verify_deployment(&id) {
        Ok(result) => Ok(Json(serde_json::to_value(result).unwrap())),
        Err(e) => Err(status_400(&e)),
    }
}

async fn software_history(Path(server): Path<String>) -> ApiResult {
    if let Some(pool) = get_db() {
        let rows: Vec<SoftwareDeploymentRow> = sqlx::query_as(&format!(
            "SELECT {DEPLOYMENT_COLUMNS} FROM software_deployments \
             WHERE server_name = $1 ORDER BY created_at, id"
        ))
        .bind(&server)
        .fetch_all(pool)
        .await
        .map_err(db_error)?;
        let records: Vec<Value> = rows.iter().map(SoftwareDeploymentRow::to_json).collect();
        return Ok(Json(json!(records)));
    }
    let history = software_deployment::get_deployment_history(&server);
    Ok(Json(serde_json::to_value(history).unwrap()))
}

async fn software_compliance(
    AuthExtractor(session): AuthExtractor,
    Query(query): Query<SoftwareComplianceQuery>,
) -> ApiResult {
    // #2: site-only compliance report — a scoped principal may only read its own
    // site (site is a required, caller-supplied param, so 403 is not an oracle);
    // an environment-scoped principal is denied (no environment axis here). Guards
    // both the DB and the no-DB engine fallback below.
    guard_body_site_scope(&session, &query.site)?;
    const VALID_SITES: &[&str] = &["DEBER", "DEFRA", "FRPAR", "GBLON", "NLAMS"];
    if !VALID_SITES.contains(&query.site.as_str()) {
        return Err(status_400(&format!("Unknown site: {}", query.site)));
    }

    // DB path: query software_deployments for completed deployments at this site.
    // DEPLOYMENT_STORE / PACKAGE_STORE are not populated from DB rows after restart,
    // so calling get_package_compliance() here would miss persisted data.
    if let Some(pool) = get_db() {
        // Approximate the same fixed server list the engine uses.
        let site_lc = query.site.to_lowercase();
        let servers = vec![
            format!("w-{}-srv-01", site_lc),
            format!("w-{}-srv-02", site_lc),
            format!("l-{}-srv-01", site_lc),
        ];

        // Fetch all approved packages that cover this site.
        let pkgs: Vec<ApprovedPackageRow> = sqlx::query_as(&format!(
            "SELECT {PACKAGE_COLUMNS} FROM approved_packages \
             WHERE site_scope = 'all' \
                OR (site_scope = 'specific' AND $1 = ANY(site_scope_list))"
        ))
        .bind(&query.site)
        .fetch_all(pool)
        .await
        .map_err(db_error)?;

        // For each package, determine which servers have a Completed deployment.
        let mut package_status: Vec<Value> = Vec::new();
        for pkg in &pkgs {
            let mut compliant: Vec<String> = Vec::new();
            let mut outdated: Vec<String> = Vec::new();
            for server in &servers {
                let done: bool = sqlx::query_scalar::<_, bool>(
                    "SELECT EXISTS( \
                         SELECT 1 FROM software_deployments \
                         WHERE server_name = $1 AND package_id = $2 AND status = 'Completed' \
                     )",
                )
                .bind(server)
                .bind(&pkg.id)
                .fetch_one(pool)
                .await
                .map_err(db_error)?;
                if done {
                    compliant.push(server.clone());
                } else {
                    outdated.push(server.clone());
                }
            }
            let pct = if servers.is_empty() {
                100.0_f64
            } else {
                (compliant.len() as f64 / servers.len() as f64) * 100.0
            };
            package_status.push(json!({
                "package_id": pkg.id,
                "package_name": pkg.name,
                "required_version": pkg.version,
                "compliant_servers": compliant,
                "outdated_servers": outdated,
                "compliance_percentage": pct,
            }));
        }

        return Ok(Json(json!({
            "source": "database",
            "generated_at": chrono::Utc::now().to_rfc3339(),
            "site": query.site,
            "servers": servers,
            "packages": package_status,
            "dry_run": true,
        })));
    }
    // No-DB fallback: engine uses PACKAGE_STORE + DEPLOYMENT_STORE (current-process only).
    match software_deployment::get_package_compliance(&query.site) {
        Ok(compliance) => Ok(Json(compliance)),
        Err(e) => Err(status_400(&e)),
    }
}

