async fn synthetic_run_check(
    AuthExtractor(session): AuthExtractor,
    Path(check_id): Path<String>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let check = crate::repos::synthetic_health::get_check(pool, &check_id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&check_id))?;
    // #2: out-of-scope -> 404 before running / persisting the check.
    scope_guard_or_404(&session, &check.site, "", &check_id)?;
    let result = synthetic_health::run_check(&check);
    let persisted = crate::repos::synthetic_health::insert_result(pool, &result)
        .await
        .map_err(db_error)?;
    Ok(Json(serde_json::to_value(persisted).unwrap_or_default()))
}

#[derive(Deserialize)]
struct SyntheticRunAllQuery {
    site: Option<String>,
}

async fn synthetic_run_all(
    AuthExtractor(session): AuthExtractor,
    Query(query): Query<SyntheticRunAllQuery>,
) -> ApiResult {
    // #2: scoped-site read (default DEFRA for an unrestricted caller).
    let site_scoped = enforce_site_scope(&session, query.site.as_deref(), "DEFRA")?;
    let site = site_scoped.as_str();
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let checks = crate::repos::synthetic_health::list_checks_for_site(pool, site)
        .await
        .map_err(db_error)?;
    let results = synthetic_health::run_all_checks(&checks);
    let mut persisted_results = Vec::with_capacity(results.len());
    for result in &results {
        let persisted = crate::repos::synthetic_health::insert_result(pool, result)
            .await
            .map_err(db_error)?;
        persisted_results.push(persisted);
    }
    Ok(Json(
        serde_json::to_value(persisted_results).unwrap_or_default(),
    ))
}

async fn synthetic_status(
    AuthExtractor(session): AuthExtractor,
    Path(check_id): Path<String>,
) -> ApiResult {
    match get_db() {
        Some(pool) => {
            // #2: the result row has no site — scope on the parent check's site;
            // out-of-scope or missing -> 404 before exposing the latest result.
            if is_scoped(&session) {
                let in_scope = crate::repos::synthetic_health::get_check(pool, &check_id)
                    .await
                    .map_err(db_error)?
                    .map(|c| row_scope_permits(&session, &c.site, ""))
                    .unwrap_or(false);
                if !in_scope {
                    return Err(status_404(&check_id));
                }
            }
            match crate::repos::synthetic_health::get_latest_result(pool, &check_id)
                .await
                .map_err(db_error)?
            {
                Some(result) => Ok(Json(serde_json::to_value(result).unwrap_or_default())),
                None => Err(status_404(&check_id)),
            }
        }
        None => Err(status_404(&check_id)),
    }
}

