/// Login request body. Deliberately no Debug/Display so the password can
/// never leak through logging. `deny_unknown_fields` so a typo'd field (e.g.
/// `passwrod`) is a hard 4xx, never a silently-dropped credential field.
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct LocalLoginRequest {
    username: String,
    password: String,
}

fn cookie_same_site_attribute(cookie_same_site: &str) -> &'static str {
    match cookie_same_site {
        "strict" => "Strict",
        "none" => "None",
        _ => "Lax",
    }
}

/// Builds the `Set-Cookie` value for the API-origin session cookie. The
/// cookie is ALWAYS HttpOnly regardless of `session.cookie_http_only`.
pub(crate) fn session_cookie_set_header(
    session_id: &str,
    session: &ryuki_core::config::SessionConfig,
) -> String {
    let mut header = format!(
        "ryuki_session={}; Path=/; HttpOnly; Max-Age={}; SameSite={}",
        session_id,
        session.cookie_max_age_secs,
        cookie_same_site_attribute(&session.cookie_same_site)
    );
    if session.cookie_secure {
        header.push_str("; Secure");
    }
    header
}

/// Builds the `Set-Cookie` value that clears the session cookie on logout.
fn session_cookie_clear_header(session: &ryuki_core::config::SessionConfig) -> String {
    let mut header = format!(
        "ryuki_session=; Path=/; HttpOnly; Max-Age=0; SameSite={}",
        cookie_same_site_attribute(&session.cookie_same_site)
    );
    if session.cookie_secure {
        header.push_str("; Secure");
    }
    header
}

/// Mode gate for POST /api/auth/local/login: only AuthMode::Local may use
/// local credential login.
fn local_login_gate(auth_mode: &AuthMode) -> Result<(), (StatusCode, Json<ApiError>)> {
    if *auth_mode == AuthMode::Local {
        Ok(())
    } else {
        Err((
            StatusCode::SERVICE_UNAVAILABLE,
            Json(ApiError::new(
                "LOCAL_AUTH_DISABLED",
                "Local authentication is not enabled",
            )),
        ))
    }
}

/// The single generic local-login failure: identical status, code, and body
/// for unknown-user, wrong-password, and throttled usernames.
fn invalid_credentials_problem() -> (StatusCode, Json<ApiError>) {
    (
        StatusCode::UNAUTHORIZED,
        Json(ApiError::new(
            "INVALID_CREDENTIALS",
            "Invalid username or password",
        )),
    )
}

/// Verifies local credentials. Failure is a single generic 401 with an
/// identical body, status, and code path for unknown-user vs wrong-password
/// (no enumeration); failure logs never include the username.
fn verify_local_credentials<'a>(
    local_auth: &'a ryuki_core::config::LocalAuthConfig,
    username: &str,
    password: &str,
) -> Result<&'a ryuki_core::config::LocalAuthUser, (StatusCode, Json<ApiError>)> {
    local_auth.verify(username, password).ok_or_else(|| {
        tracing::warn!("local login failed");
        invalid_credentials_problem()
    })
}

// ─── Local login brute-force throttle ───

/// Consecutive failures per username after which local login attempts are
/// rejected without credential verification.
const LOCAL_LOGIN_LOCKOUT_THRESHOLD: u32 = 5;

/// Uniform delay applied to EVERY failed local login attempt — wrong
/// credentials and throttled usernames alike — so failure timing carries no
/// signal about lockout state.
const LOCAL_LOGIN_FAILURE_DELAY: std::time::Duration = std::time::Duration::from_millis(500);

/// Failure entries older than this are pruned: a lockout naturally expires
/// after 15 minutes without further failed attempts, and the tracker never
/// retains stale usernames.
const LOCAL_LOGIN_TRACKER_RETENTION: std::time::Duration = std::time::Duration::from_secs(15 * 60);

/// Hard cap on tracked usernames so attacker-chosen usernames cannot grow
/// the tracker unbounded; the stalest entry is evicted at the cap.
const LOCAL_LOGIN_TRACKER_MAX_ENTRIES: usize = 1024;

struct LocalLoginFailureEntry {
    consecutive_failures: u32,
    last_failure: std::time::Instant,
}

/// In-process per-username failed-attempt tracker for
/// POST /api/auth/local/login. Held in the router as an `Extension` (created
/// in `main`, no global mutable state). Source-address (ConnectInfo) keyed
/// rate limiting is a separate, later wave.
#[derive(Default)]
pub struct LocalLoginThrottle {
    // Lock acquisitions below recover from poisoning via
    // `unwrap_or_else(|e| e.into_inner())`: a panic in another thread's
    // critical section must not turn every subsequent login into a panic
    // (an auth-path DoS). Mirrors the metrics-mutex recovery in main.rs.
    entries: std::sync::Mutex<std::collections::HashMap<String, LocalLoginFailureEntry>>,
}

impl LocalLoginThrottle {
    fn prune(
        entries: &mut std::collections::HashMap<String, LocalLoginFailureEntry>,
        now: std::time::Instant,
    ) {
        entries.retain(|_, entry| {
            now.duration_since(entry.last_failure) < LOCAL_LOGIN_TRACKER_RETENTION
        });
    }

    fn is_locked_out_at(&self, username: &str, now: std::time::Instant) -> bool {
        let mut entries = self.entries.lock().unwrap_or_else(|e| e.into_inner());
        Self::prune(&mut entries, now);
        entries
            .get(username)
            .is_some_and(|entry| entry.consecutive_failures >= LOCAL_LOGIN_LOCKOUT_THRESHOLD)
    }

    fn record_failure_at(&self, username: &str, now: std::time::Instant) {
        let mut entries = self.entries.lock().unwrap_or_else(|e| e.into_inner());
        Self::prune(&mut entries, now);
        if !entries.contains_key(username) && entries.len() >= LOCAL_LOGIN_TRACKER_MAX_ENTRIES {
            // Evict the stalest entry so the tracker stays bounded.
            if let Some(stalest) = entries
                .iter()
                .min_by_key(|(_, entry)| entry.last_failure)
                .map(|(username, _)| username.clone())
            {
                entries.remove(&stalest);
            }
        }
        let entry = entries
            .entry(username.to_string())
            .or_insert(LocalLoginFailureEntry {
                consecutive_failures: 0,
                last_failure: now,
            });
        entry.consecutive_failures = entry.consecutive_failures.saturating_add(1);
        entry.last_failure = now;
    }

    fn is_locked_out(&self, username: &str) -> bool {
        self.is_locked_out_at(username, std::time::Instant::now())
    }

    fn record_failure(&self, username: &str) {
        self.record_failure_at(username, std::time::Instant::now());
    }

    fn record_success(&self, username: &str) {
        self.entries
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .remove(username);
    }
}

/// Canonical login response body (seam shared with the portal — see the
/// fixture tests; field changes break the portal DTO).
fn local_login_response_body(
    session_id: &Uuid,
    username: &str,
    roles: &[String],
    expires_at: &chrono::DateTime<chrono::Utc>,
) -> Value {
    json!({
        "session_id": session_id.to_string(),
        "user_id": username,
        "display_name": username,
        "roles": roles,
        "token_valid": true,
        "provider_mode": "local",
        "expires_at": expires_at.to_rfc3339(),
    })
}

async fn auth_local_login(
    Extension(throttle): Extension<std::sync::Arc<LocalLoginThrottle>>,
    Json(body): Json<LocalLoginRequest>,
) -> Result<Response, (StatusCode, Json<ApiError>)> {
    let app_cfg = crate::config_store::get_app_config();
    local_login_gate(&app_cfg.auth_mode)?;

    // Brute-force throttle: locked-out usernames are rejected WITHOUT
    // credential verification, with the same generic 401 body and the same
    // uniform failure delay as a wrong credential, so lockout state cannot
    // be probed. Throttle logs never include the username.
    if throttle.is_locked_out(&body.username) {
        throttle.record_failure(&body.username);
        tracing::warn!("local login rejected by failed-attempt throttle");
        tokio::time::sleep(LOCAL_LOGIN_FAILURE_DELAY).await;
        return Err(invalid_credentials_problem());
    }

    let user = match verify_local_credentials(&app_cfg.local_auth, &body.username, &body.password) {
        Ok(user) => {
            throttle.record_success(&body.username);
            user
        }
        Err(problem) => {
            throttle.record_failure(&body.username);
            tokio::time::sleep(LOCAL_LOGIN_FAILURE_DELAY).await;
            return Err(problem);
        }
    };

    // Local sessions are never minted in-memory: a database is required.
    let Some(pool) = get_db() else {
        tracing::error!("local login requires a database for session persistence");
        return Err(auth_session_persistence_problem());
    };

    // Session fixation defense: the session id is generated server-side at
    // login, one fresh session per login; client-supplied ids are never
    // accepted for creation.
    let session_id = Uuid::new_v4();
    let expires_at: chrono::DateTime<chrono::Utc> = map_auth_session_persistence_result(
        sqlx::query_scalar(
            "INSERT INTO sessions (id, user_id, display_name, roles, provider, expires_at) \
             VALUES ($1, $2, $3, $4, 'local', NOW() + make_interval(secs => $5)) \
             RETURNING expires_at",
        )
        .bind(session_id)
        .bind(&user.username)
        .bind(&user.username)
        .bind(&user.roles)
        .bind(app_cfg.session.cookie_max_age_secs as f64)
        .fetch_one(pool)
        .await,
        "create",
    )?;

    // Success log: username + session creation only. Never the password, and
    // never the session_id — it IS the bearer cookie credential.
    tracing::info!(username = %user.username, "local login session created");

    let response_body =
        local_login_response_body(&session_id, &user.username, &user.roles, &expires_at);
    let cookie = session_cookie_set_header(&session_id.to_string(), &app_cfg.session);
    Ok(([(SET_COOKIE, cookie)], Json(response_body)).into_response())
}

/// One persisted session row, used by the logout path to capture actor identity
/// for the `session.logout` audit row before the row is deleted.
#[derive(sqlx::FromRow)]
struct LogoutSessionRow {
    user_id: String,
    display_name: String,
    roles: Vec<String>,
}

/// Logs the caller out of their OWN session and ONLY their own session (B4).
///
/// The session id is resolved exclusively from the caller's own credential
/// surface (`X-Ryuki-Session-Id`, `Authorization: Bearer <uuid>`, then the
/// `ryuki_session` cookie) via `session_id_from_headers` — there is NO
/// client-supplied body id, so no victim-id termination vector exists. The
/// flow is: resolve id -> best-effort SELECT for actor attribution -> DELETE
/// that one id -> best-effort `session.logout` audit row. It is idempotent: a
/// missing/invalid/expired session simply records nothing and returns. Audit
/// or DB failures never change the caller's logout outcome.
async fn logout_caller_session(headers: &HeaderMap) {
    let auth_header = headers.get("Authorization").and_then(|h| h.to_str().ok());
    let Some((Ok(session_id), _source)) = crate::session_id_from_headers(headers, auth_header)
    else {
        // No resolvable session id on the caller's own surface: nothing to
        // delete, idempotent no-op.
        return;
    };
    let Some(pool) = get_db() else {
        return;
    };

    // Best-effort: capture actor identity BEFORE deleting so the logout audit
    // row carries the real principal/roles. A miss falls back to an
    // unverified "local-logout" actor.
    let row: Option<LogoutSessionRow> =
        sqlx::query_as("SELECT user_id, display_name, roles FROM sessions WHERE id = $1")
            .bind(session_id)
            .fetch_optional(pool)
            .await
            .unwrap_or(None);

    let delete_result = sqlx::query("DELETE FROM sessions WHERE id = $1")
        .bind(session_id)
        .execute(pool)
        .await;

    match delete_result {
        Ok(_) => {
            // Never log the session_id — it is the bearer cookie credential.
            tracing::info!("logout deleted caller session");
            let actor = match row {
                Some(r) => AuthSession {
                    user_id: r.user_id,
                    display_name: r.display_name,
                    roles: r.roles,
                    token_valid: true,
                    provider_mode: "persisted-session".into(),
                    ..Default::default()
                },
                None => crate::unverified_session("local-logout"),
            };
            audit::record_denied(
                get_db(),
                &actor,
                &AuditRecord {
                    action: "session.logout",
                    request_id: None,
                    from_status: None,
                    to_status: "logged_out",
                    from_stage: None,
                    to_stage: "logout",
                    detail: json!({}),
                    outcome: "applied",
                },
            )
            .await;
        }
        Err(error) => {
            // A delete failure never changes the 200 — log and move on so an
            // expired session can still clear cookies.
            tracing::warn!(error = %error, "logout session delete failed (best-effort)");
        }
    }
}

async fn auth_local_logout(headers: HeaderMap) -> Result<Response, (StatusCode, Json<ApiError>)> {
    // B4: delete ONLY the caller's own resolved session; idempotent; writes a
    // best-effort session.logout audit row. Always returns 200 + clear-cookie.
    logout_caller_session(&headers).await;
    let app_cfg = crate::config_store::get_app_config();
    let cookie = session_cookie_clear_header(&app_cfg.session);
    Ok((
        [(SET_COOKIE, cookie)],
        Json(json!({"status": "logged_out"})),
    )
        .into_response())
}

/// OIDC browser sign-in — login initiation (auth-code + PKCE, S256 only).
///
/// Generates a cryptographically random `state`, `nonce`, and PKCE
/// `code_verifier` (all via OsRng / getrandom), persists them to the
/// `oidc_login_states` table, then redirects the browser to the IdP's
/// authorization endpoint with the full set of OAuth2/OIDC parameters.
///
/// # Security properties
/// - `state` / `nonce` / `pkce_verifier`: 32 bytes from OsRng → ≥256-bit
///   entropy; base64url-encoded (URL_SAFE_NO_PAD).
/// - `code_challenge` = BASE64URL(SHA-256(pkce_verifier_bytes)); method = S256.
/// - `state` is single-use and expires in 10 minutes (enforced by `take`
///   in slice 2 and by the DB `expires_at` column).
/// - All authorize-URL query parameters are percent-encoded by the `url` crate,
///   preventing injection via `redirect_uri`, `scope`, or `client_id`.
/// - No session cookie is set; no sensitive value is included in the redirect.
async fn oidc_login_initiate() -> Result<Response, (StatusCode, Json<Value>)> {
    use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine as _};
    use rand::RngCore;
    use url::Url;

    let cfg = crate::config_store::get_app_config();
    let oidc = &cfg.oidc;

    // Gate: return 404 when OIDC is not configured, so callers cannot probe
    // for the existence of the endpoint on instances that don't enable it.
    if !oidc.enabled {
        return Err((
            StatusCode::NOT_FOUND,
            Json(json!({"error": "OIDC login is not enabled"})),
        ));
    }

    // Gate: a DB is required to persist the state (single-use, short-lived).
    let pool = get_db().ok_or_else(status_503_no_db)?;

    // ── Generate CSPRNG values ────────────────────────────────────────────────
    // OsRng is backed by getrandom (OS entropy). 32 bytes = 256 bits of entropy.

    let mut state_bytes = [0u8; 32];
    rand::rngs::OsRng.fill_bytes(&mut state_bytes);
    let state = URL_SAFE_NO_PAD.encode(state_bytes);

    let mut nonce_bytes = [0u8; 32];
    rand::rngs::OsRng.fill_bytes(&mut nonce_bytes);
    let nonce = URL_SAFE_NO_PAD.encode(nonce_bytes);

    let mut pkce_bytes = [0u8; 32];
    rand::rngs::OsRng.fill_bytes(&mut pkce_bytes);
    let pkce_verifier = URL_SAFE_NO_PAD.encode(pkce_bytes);

    // PKCE S256: code_challenge = BASE64URL(SHA-256(ASCII(code_verifier)))
    let code_challenge = URL_SAFE_NO_PAD.encode(Sha256::digest(pkce_verifier.as_bytes()));

    // Per-browser CSRF binding: stored with the state AND set as an HttpOnly
    // cookie below. The callback redeems the state only when the cookie matches,
    // so a state obtained from an attacker's own flow cannot be replayed in a
    // victim's browser (login-CSRF / session-swapping defense).
    let mut binding_bytes = [0u8; 32];
    rand::rngs::OsRng.fill_bytes(&mut binding_bytes);
    let binding = URL_SAFE_NO_PAD.encode(binding_bytes);

    // ── Persist state (single-use, 10-minute TTL) ────────────────────────────
    crate::repos::oidc_login_states::insert(pool, &state, &nonce, &pkce_verifier, &binding)
        .await
        .map_err(db_error)?;

    // Opportunistic, PROBABILISTIC sweep of expired rows (~1/64 of requests):
    // keeps the index-backed cleanup off the hot path so a flood on this
    // auth-exempt endpoint can't turn every login into a DELETE. The 10-minute
    // TTL + the expires_at index bound the table; request-rate limiting itself is
    // an infra-level (gateway) control, consistent with the rest of the auth
    // surface. Failure is non-fatal.
    if rand::random::<u8>() < 4 {
        let _ = crate::repos::oidc_login_states::cleanup_expired(pool).await;
    }

    // ── Build the authorize URL ───────────────────────────────────────────────
    // All parameter values are percent-encoded by url::Url::parse_with_params,
    // preventing injection through any field (redirect_uri, scope, client_id).
    let scope = oidc.scopes.join(" ");
    let params: Vec<(&str, &str)> = vec![
        ("response_type", "code"),
        ("client_id", &oidc.client_id),
        ("redirect_uri", &oidc.redirect_uri),
        ("scope", &scope),
        ("state", &state),
        ("nonce", &nonce),
        ("code_challenge", &code_challenge),
        ("code_challenge_method", "S256"),
    ];
    let authorize_url = Url::parse_with_params(&oidc.authorize_endpoint, &params).map_err(|e| {
        tracing::error!(error = %e, "failed to build OIDC authorize URL");
        (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({"error": "failed to build authorization URL"})),
        )
    })?;

    // 302 → IdP. No session cookie. No sensitive value in the Location header.
    let location = axum::http::HeaderValue::from_str(authorize_url.as_str()).map_err(|e| {
        (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({"error": format!("invalid redirect URL: {e}")})),
        )
    })?;
    // Set the per-browser CSRF binding cookie. SameSite=Lax is REQUIRED so the
    // browser sends it on the top-level redirect BACK from the IdP to the
    // callback (a cross-site navigation); Secure follows the session policy.
    // Short-lived to match the state TTL. The value is base64url (cookie-safe).
    let binding_cookie = format!(
        "oidc_login_csrf={}; Path=/; HttpOnly; Max-Age=600; SameSite=Lax{}",
        binding,
        if cfg.session.cookie_secure {
            "; Secure"
        } else {
            ""
        }
    );
    let cookie_hv = axum::http::HeaderValue::from_str(&binding_cookie).map_err(|e| {
        (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({"error": format!("cookie encoding failed: {e}")})),
        )
    })?;
    Ok((
        StatusCode::FOUND,
        [
            (axum::http::header::LOCATION, location),
            (axum::http::header::SET_COOKIE, cookie_hv),
        ],
    )
        .into_response())
}

async fn auth_status() -> Json<Value> {
    let app_cfg = crate::config_store::get_app_config();
    let tenant_configured = !app_cfg.entra_tenant_id.is_empty();
    let client_configured = !app_cfg.entra_client_id.is_empty();
    Json(json!({
        "tenant_configured": tenant_configured,
        "client_configured": client_configured,
        "enabled": tenant_configured && client_configured,
        "instance": app_cfg.entra_authority,
    }))
}

