const AUTH_SESSION_PERSISTENCE_FAILED: &str = "AUTH_SESSION_PERSISTENCE_FAILED";

fn auth_session_persistence_problem() -> (StatusCode, Json<ApiError>) {
    (
        StatusCode::INTERNAL_SERVER_ERROR,
        Json(ApiError::new(
            AUTH_SESSION_PERSISTENCE_FAILED,
            "Auth session could not be persisted",
        )),
    )
}

pub(crate) fn map_auth_session_persistence_result<T, E: std::fmt::Display>(
    result: Result<T, E>,
    operation: &str,
) -> Result<T, (StatusCode, Json<ApiError>)> {
    result.map_err(|error| {
        tracing::error!(
            operation,
            error = %error,
            "auth session persistence failed"
        );
        auth_session_persistence_problem()
    })
}

fn static_login_roles() -> [&'static str; 2] {
    [
        ryuki_engine::auth::APP_ROLE_PLATFORM_ADMIN,
        ryuki_engine::auth::APP_ROLE_VMWARE_OPERATOR,
    ]
}

/// Mode gate for POST /api/auth/login: the anonymous mock mint only exists in
/// the dry-run modes. In Local mode it would bypass local auth entirely, so
/// it is rejected with a pointer at the local login endpoint.
fn mock_login_gate(auth_mode: &AuthMode) -> Result<(), (StatusCode, Json<ApiError>)> {
    match auth_mode {
        AuthMode::MockDryRun | AuthMode::StaticDryRun => Ok(()),
        AuthMode::Local => Err((
            StatusCode::SERVICE_UNAVAILABLE,
            Json(ApiError::new(
                "LOCAL_AUTH_MODE",
                "Use /api/auth/local/login in local auth mode",
            )),
        )),
        AuthMode::EntraId => Err((
            StatusCode::SERVICE_UNAVAILABLE,
            Json(ApiError::new(
                "ENTRA_NOT_CONFIGURED",
                "Entra SSO not configured",
            )),
        )),
    }
}

async fn auth_login() -> Result<Json<Value>, (StatusCode, Json<ApiError>)> {
    let app_cfg = crate::config_store::get_app_config();
    mock_login_gate(&app_cfg.auth_mode)?;

    let session_id = Uuid::new_v4();
    let roles = static_login_roles();
    let session_data = json!({
        "session_id": session_id.to_string(),
        "user_id": "platform-engineer",
        "display_name": "Platform Engineer",
        "email": "platform-engineer@ryuki.local",
        "roles": roles,
        "token_valid": false,
        "provider_mode": "static-dry-run"
    });

    if let Some(pool) = get_db() {
        map_auth_session_persistence_result(
            sqlx::query(
                "INSERT INTO sessions (id, user_id, display_name, email, roles, provider) \
                 VALUES ($1, $2, $3, $4, $5, 'static-dry-run')",
            )
            .bind(session_id)
            .bind("platform-engineer")
            .bind("Platform Engineer")
            .bind("platform-engineer@ryuki.local")
            .bind(&roles as &[&str])
            .execute(pool)
            .await,
            "create",
        )?;
    }

    Ok(Json(session_data))
}

/// POST /api/auth/logout — the Entra/mock logout path.
///
/// B4: takes ONLY the request headers (no `Json(body)`), so a client-supplied
/// `session_id` can never terminate a victim's session. The caller's own id is
/// resolved from their credential surface and only that session is deleted.
/// Idempotent: an expired/missing session still returns 200.
async fn auth_logout(headers: HeaderMap) -> Result<Json<Value>, (StatusCode, Json<ApiError>)> {
    logout_caller_session(&headers).await;
    Ok(Json(json!({"status": "logged_out"})))
}

