fn require_admin_permission(session: &AuthSession) -> Result<(), (StatusCode, Json<ApiError>)> {
    if check_permission(session, "admin") {
        Ok(())
    } else {
        Err((
            StatusCode::FORBIDDEN,
            Json(ApiError::new("FORBIDDEN", "Admin permission required")),
        ))
    }
}

/// Interactive external identity modes that may write platform settings.
/// Long-lived non-interactive credentials — the browser `persisted-session`
/// and machine `api-token` — are deliberately excluded: settings writes
/// (auth mode, Entra config) require a freshly verified interactive admin so a
/// stolen or over-scoped standing credential cannot rewrite the auth posture.
fn is_interactive_external_admin(session: &AuthSession) -> bool {
    session.token_valid
        && session.provider_mode != "persisted-session"
        && session.provider_mode != "api-token"
}

fn require_verified_external_admin_permission(
    session: &AuthSession,
    auth_mode: &AuthMode,
) -> Result<(), (StatusCode, Json<ApiError>)> {
    require_admin_permission(session)?;
    if is_interactive_external_admin(session) {
        return Ok(());
    }
    // Local-mode bootstrap (breaks the circular onboarding where you cannot
    // configure Entra without first writing settings, but settings writes
    // required an external Entra admin). When the platform runs in LOCAL auth
    // mode there is no external IdP to authenticate against, so the verified
    // local admin IS the configured trust anchor and may write settings.
    //
    // Tightly scoped, never weakening the Entra path:
    //   - only when the RUNTIME auth_mode is Local (not Entra, not the dry-run
    //     demo modes — so the static demo's preview-only writes are unchanged),
    //   - only a verified (token_valid) admin session,
    //   - NEVER a machine `api-token` identity (preserves the credential-
    //     escalation guard: a standing token can never write settings).
    if *auth_mode == AuthMode::Local && session.token_valid && session.provider_mode != "api-token"
    {
        return Ok(());
    }
    Err((
        StatusCode::UNAUTHORIZED,
        Json(ApiError::new(
            "VERIFIED_ADMIN_REQUIRED",
            "Verified external admin authentication is required for platform settings writes",
        )),
    ))
}

fn apply_platform_config_entry(config: &mut PlatformConfig, key: &str, value: &str) {
    match key {
        "entra_tenant_id" => config.entra_tenant_id = value.to_string(),
        "entra_client_id" => config.entra_client_id = value.to_string(),
        "entra_authority" => config.entra_authority = value.to_string(),
        "auth_mode" => config.auth_mode = value.to_string(),
        "database_provider" => config.database_provider = value.to_string(),
        "platform_name" => config.platform_name = value.to_string(),
        "platform_url" => config.platform_url = value.to_string(),
        "secret_provider" => config.secret_provider = value.to_string(),
        "kubernetes_runtime" => config.kubernetes_runtime = value.to_string(),
        "monitoring_provider" => config.monitoring_provider = value.to_string(),
        "backup_provider" => config.backup_provider = value.to_string(),
        "hypervisor_provider" => config.hypervisor_provider = value.to_string(),
        "storage_provider" => config.storage_provider = value.to_string(),
        "dns_provider" => config.dns_provider = value.to_string(),
        "ipam_provider" => config.ipam_provider = value.to_string(),
        "load_balancer_provider" => config.load_balancer_provider = value.to_string(),
        "firewall_provider" => config.firewall_provider = value.to_string(),
        "build_provider" => config.build_provider = value.to_string(),
        "network_provider" => config.network_provider = value.to_string(),
        "retention_daily_backups" => {
            if let Ok(parsed) = value.parse() {
                config.retention_daily_backups = parsed;
            }
        }
        "retention_weekly_backups" => {
            if let Ok(parsed) = value.parse() {
                config.retention_weekly_backups = parsed;
            }
        }
        "retention_monthly_backups" => {
            if let Ok(parsed) = value.parse() {
                config.retention_monthly_backups = parsed;
            }
        }
        "retention_yearly_backups" => {
            if let Ok(parsed) = value.parse() {
                config.retention_yearly_backups = parsed;
            }
        }
        "maintenance_window_day" => config.maintenance_window_day = value.to_string(),
        "maintenance_window_start_hour" => {
            if let Ok(parsed) = value.parse() {
                config.maintenance_window_start_hour = parsed;
            }
        }
        "maintenance_window_duration_hours" => {
            if let Ok(parsed) = value.parse() {
                config.maintenance_window_duration_hours = parsed;
            }
        }
        "keep_alive_timeout_secs" => {
            if let Ok(parsed) = value.parse() {
                config.keep_alive_timeout_secs = parsed;
            }
        }
        "max_concurrent_connections" => {
            if let Ok(parsed) = value.parse() {
                config.max_concurrent_connections = parsed;
            }
        }
        _ => {}
    }
}

