// ─── Backup Coverage & Restore handlers ───

async fn backup_coverage_report(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<CoverageReportRequest>,
) -> ApiResult {
    // #2: a coverage report spans the caller-supplied site/environment vectors. A
    // scoped principal may only request a report whose footprint is contained in
    // its authority on BOTH axes (subset containment) — an empty (all-sites or
    // all-envs) request from a scoped principal is denied. Body-supplied → 403.
    if is_scoped(&session) {
        if !within_multi_scope(&session.site_scope, &body.site_scope) {
            return Err(status_403_out_of_scope("site"));
        }
        if !within_multi_scope(&session.environment_scope, &body.environment_scope) {
            return Err(status_403_out_of_scope("environment"));
        }
    }
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let mut report =
        backup_engine::generate_backup_coverage_report(&body.site_scope, &body.environment_scope)
            .map_err(|e| status_400(&e))?;

    // The engine mints a non-UUID id (e.g. "bcr-abc12345") suitable for
    // in-memory use but not for the UUID primary key column. Replace it with a
    // proper UUID so the repo can bind it correctly.
    report.id = Uuid::new_v4().to_string();

    let persisted = crate::repos::backup_coverage_reports::insert(pool, &report)
        .await
        .map_err(db_error)?;

    Ok(Json(serde_json::to_value(&persisted).unwrap_or_default()))
}

async fn backup_restore_plan(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<RestorePlanRequest>,
) -> ApiResult {
    // #2 dual-axis WRITE: a scoped principal may only plan a restore whose target
    // site AND environment are both within its scope (body-supplied → 403, no
    // existence oracle).
    guard_body_scope_dual(&session, &body.target_site, &body.target_environment)?;
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let restore_type = match body.restore_type.as_str() {
        "full-vm" => ryuki_engine::models::RestoreType::FullVm,
        "file-level" => ryuki_engine::models::RestoreType::FileLevel,
        "application-item" => ryuki_engine::models::RestoreType::ApplicationItem,
        "instant-vm-recovery" => ryuki_engine::models::RestoreType::InstantVmRecovery,
        _ => return Err(status_400("Invalid restore type")),
    };

    let mut restore = backup_engine::plan_restore(
        &body.source_ci_key,
        restore_type,
        &body.restore_point,
        &body.target_site,
        &body.target_environment,
        &body.owner,
    )
    .map_err(|e| status_400(&e))?;

    // The engine mints a non-UUID id (e.g. "rest-abc12345") suitable for
    // in-memory use but not for the UUID primary key column. Replace it with a
    // proper UUID so the repo can bind it correctly.
    restore.id = Uuid::new_v4().to_string();

    let persisted = crate::repos::restore_requests::insert(pool, &restore)
        .await
        .map_err(db_error)?;

    Ok(Json(serde_json::to_value(&persisted).unwrap_or_default()))
}

