// ─── Server Decommission handlers ───

/// 503 returned by handlers that require a database when no pool is available.
pub(crate) fn status_503_no_db() -> (StatusCode, Json<Value>) {
    (
        StatusCode::SERVICE_UNAVAILABLE,
        Json(json!({"error": "persistence required: this operation requires a database"})),
    )
}

/// 403 for a request that names (or, while scoped, omits) a scope the principal
/// is not authorized for (#2). `dimension` is "site" or "environment".
fn status_403_out_of_scope(dimension: &str) -> (StatusCode, Json<Value>) {
    (
        StatusCode::FORBIDDEN,
        Json(json!({
            "error": format!("requested {dimension} is outside your authorized scope"),
        })),
    )
}

/// The effective `(site, environment)` filters a scoped read must query with
/// after [`enforce_scope_filters`] has applied the principal's scopes.
type ScopeFilters = (Option<String>, Option<String>);

/// Enforce the session's site/environment scopes (#2) against the requested
/// filters, returning the EFFECTIVE filters the handler must query with.
///
/// #10: enforce the `write-execution-blocked-when-degraded` degradation rule —
/// refuse a live-execution grant when the target site is degraded or
/// unreachable. The persisted site_status (swarm #8) is authoritative; a
/// healthy/recovering site, or one with no status row, is allowed. A DB read
/// error is allowed (fail-open + logged) so a transient status-store blip cannot
/// block ALL live execution — matching the degradation read-path posture.
pub(crate) async fn enforce_site_operational(
    pool: &sqlx::PgPool,
    site: &str,
) -> Result<(), (StatusCode, Json<Value>)> {
    use ryuki_engine::degradation_mode::SiteDegradationState;
    match crate::repos::degradation::get_site_status(pool, site).await {
        Ok(Some(s))
            if s.state == SiteDegradationState::Degraded
                || s.state == SiteDegradationState::Unreachable =>
        {
            Err((
                StatusCode::SERVICE_UNAVAILABLE,
                Json(json!({
                    "error": format!(
                        "site '{site}' is in degradation mode (state: {}); live write execution is blocked until it recovers",
                        s.state
                    ),
                    "site": site,
                    "state": s.state.to_string(),
                })),
            ))
        }
        Ok(_) => Ok(()),
        Err(e) => {
            tracing::warn!(error = %e, %site, "degradation gate: site_status read failed; allowing execution (fail-open)");
            Ok(())
        }
    }
}

/// Security contract: an UNRESTRICTED principal (empty scope) reads any scope
/// (the filters pass through verbatim). A SCOPED principal may only read within
/// its authorized scopes — and crucially, omitting the filter NARROWS the read
/// to its own scope rather than widening it to all scopes. A request for an
/// out-of-scope value, or an omitted filter from a principal holding several
/// scopes, is a 403. Inputs should already be trimmed/normalized (blank ⇒ None).
fn enforce_scope_filters(
    session: &AuthSession,
    site: Option<String>,
    environment: Option<String>,
) -> Result<ScopeFilters, (StatusCode, Json<Value>)> {
    use ryuki_engine::auth::{resolve_scope_filter, ScopeFilter};
    let site = match resolve_scope_filter(&session.site_scope, site.as_deref()) {
        ScopeFilter::Allow(v) => v,
        ScopeFilter::Deny => return Err(status_403_out_of_scope("site")),
    };
    let environment = match resolve_scope_filter(&session.environment_scope, environment.as_deref())
    {
        ScopeFilter::Allow(v) => v,
        ScopeFilter::Deny => return Err(status_403_out_of_scope("environment")),
    };
    Ok((site, environment))
}

/// Resolve the effective `site` for a SITE-ONLY read (analytics/capacity) under
/// the session's site scope (#2). `default_site` is applied ONLY for an
/// UNRESTRICTED principal that named no site — a scoped principal is narrowed to
/// its own scope (or 403'd), never silently defaulted to a site that may be out
/// of scope. These reads have no environment axis (they span all environments of
/// a site), so an environment-scoped principal is denied rather than leaked
/// cross-environment data.
fn enforce_site_scope(
    session: &AuthSession,
    requested: Option<&str>,
    default_site: &str,
) -> Result<String, (StatusCode, Json<Value>)> {
    use ryuki_engine::auth::{resolve_scope_filter, ScopeFilter};
    if session
        .environment_scope
        .iter()
        .any(|s| !s.trim().is_empty())
    {
        return Err(status_403_out_of_scope("environment"));
    }
    match resolve_scope_filter(&session.site_scope, requested) {
        // Scoped (or explicit) value resolved to a concrete in-scope site.
        ScopeFilter::Allow(Some(s)) => Ok(s),
        // Unrestricted principal that named no site → keep the legacy default.
        ScopeFilter::Allow(None) => Ok(default_site.to_string()),
        ScopeFilter::Deny => Err(status_403_out_of_scope("site")),
    }
}

/// Body-scope guard for a site-only WRITE (#2): a scoped principal may only
/// create/act on a resource in its own site. An out-of-scope site is a 403, and
/// an environment-scoped principal is denied (these resources — DNS records,
/// IPAM subnets, firewall rules, storage volumes/arrays — have NO environment
/// axis, so an environment scope cannot be honored). Pass the body's CONCRETE,
/// required site value (non-`Option`), so the `scope_permits(None)=unconstrained`
/// fail-open never applies.
fn guard_body_site_scope(
    session: &AuthSession,
    site: &str,
) -> Result<(), (StatusCode, Json<Value>)> {
    if session
        .environment_scope
        .iter()
        .any(|s| !s.trim().is_empty())
    {
        return Err(status_403_out_of_scope("environment"));
    }
    if ryuki_engine::auth::scope_permits(&session.site_scope, Some(site)) {
        Ok(())
    } else {
        Err(status_403_out_of_scope("site"))
    }
}

/// Retain only the list-all rows a principal may see (#2): unrestricted keeps
/// all rows; a site-scoped principal keeps only its own site's rows; an
/// environment-scoped principal keeps NONE — these list-all resources are
/// site-only, so an environment scope cannot be honored and we fail closed to an
/// empty result rather than leak every site. For the no-param "list everything"
/// reads that have no `?site` to narrow.
fn retain_site_scoped<T>(
    session: &AuthSession,
    rows: Vec<T>,
    site_of: impl Fn(&T) -> &str,
) -> Vec<T> {
    use ryuki_engine::auth::scope_permits;
    if session
        .environment_scope
        .iter()
        .any(|s| !s.trim().is_empty())
    {
        return Vec::new();
    }
    rows.into_iter()
        .filter(|r| scope_permits(&session.site_scope, Some(site_of(r))))
        .collect()
}

/// Body-scope guard for a DUAL-axis WRITE (#2): a scoped principal may only
/// create/act on a resource whose site AND environment are both within its
/// scope (e.g. a Kubernetes namespace, which is keyed on both). Reports the
/// specific failing axis. Pass the body's CONCRETE required values.
fn guard_body_scope_dual(
    session: &AuthSession,
    site: &str,
    environment: &str,
) -> Result<(), (StatusCode, Json<Value>)> {
    use ryuki_engine::auth::scope_permits;
    if !scope_permits(&session.site_scope, Some(site)) {
        return Err(status_403_out_of_scope("site"));
    }
    if !scope_permits(&session.environment_scope, Some(environment)) {
        return Err(status_403_out_of_scope("environment"));
    }
    Ok(())
}

/// Whether a principal may access a by-id row given the row's CONCRETE,
/// already-loaded site/environment (#2). Unlike the query-param helpers, this is
/// the POST-LOAD guard for request-by-id reads: the scope value lives on the row,
/// not the request. Pass the loaded values directly — they are non-nullable on
/// `requests`, so the `scope_permits(None)=unconstrained` fail-open never applies.
fn row_scope_permits(session: &AuthSession, site: &str, environment: &str) -> bool {
    use ryuki_engine::auth::scope_permits;
    scope_permits(&session.site_scope, Some(site))
        && scope_permits(&session.environment_scope, Some(environment))
}

/// Post-load by-id scope guard that maps an out-of-scope row to the SAME 404 a
/// missing row produces (#2) — so a by-id endpoint is never a cross-scope
/// existence/enumeration oracle for a scoped principal.
fn scope_guard_or_404(
    session: &AuthSession,
    site: &str,
    environment: &str,
    request_id: &str,
) -> Result<(), (StatusCode, Json<Value>)> {
    if row_scope_permits(session, site, environment) {
        Ok(())
    } else {
        Err(status_404(request_id))
    }
}

/// Post-load by-id scope guard for a SITE-ONLY resource — one with no environment
/// axis (e.g. a decommission request keyed on site alone) (#2). Maps any
/// out-of-scope or unsatisfiable access to the SAME 404 a missing row produces, so
/// the endpoint is never a cross-scope existence oracle. An environment-scoped
/// principal cannot be honored by a site-only resource, so it fails closed to a
/// 404 — the by-id mirror of `retain_site_scoped` returning an empty list.
fn site_scope_guard_or_404(
    session: &AuthSession,
    site: &str,
    request_id: &str,
) -> Result<(), (StatusCode, Json<Value>)> {
    let env_scoped = session
        .environment_scope
        .iter()
        .any(|s| !s.trim().is_empty());
    if !env_scoped && ryuki_engine::auth::scope_permits(&session.site_scope, Some(site)) {
        Ok(())
    } else {
        Err(status_404(request_id))
    }
}

/// Post-load by-id guard for a SITE-ONLY resource whose site is NULLABLE (NULL =
/// platform-wide) (#2) — e.g. an on-call contact. A row tagged to a concrete site
/// follows the normal site_scope_guard_or_404 rule; a platform-wide (NULL) row is
/// accessible only to an UNRESTRICTED principal, because a scoped principal cannot
/// contain an all-sites footprint, so it 404s. This is the single-axis analogue of
/// the nullable dual-axis containment used for metric_budgets / slo.
fn nullable_site_scope_guard_or_404(
    session: &AuthSession,
    site: Option<&str>,
    request_id: &str,
) -> Result<(), (StatusCode, Json<Value>)> {
    match site {
        Some(s) => site_scope_guard_or_404(session, s, request_id),
        None if is_scoped(session) => Err(status_404(request_id)),
        None => Ok(()),
    }
}

/// True iff the principal is scoped on EITHER axis (has any non-blank site or
/// environment scope). Used to skip an extra pre-load round-trip for the common
/// unrestricted case while still fail-closing for any scoped principal (#2).
fn is_scoped(session: &AuthSession) -> bool {
    session.site_scope.iter().any(|s| !s.trim().is_empty())
        || session
            .environment_scope
            .iter()
            .any(|s| !s.trim().is_empty())
}

/// Per-axis containment for a resource that TARGETS a set of values (e.g. a patch
/// wave's `site_scope` / `environment_scope`) rather than living at one site (#2).
/// An unrestricted principal (blank scope vec) always passes; a scoped principal
/// requires the resource's list to be NON-EMPTY and every entry permitted — an
/// empty resource list means "all" and so fails closed for a scoped caller.
fn within_multi_scope(principal: &[String], resource: &[String]) -> bool {
    use ryuki_engine::auth::scope_permits;
    if principal.iter().all(|s| s.trim().is_empty()) {
        return true; // unrestricted on this axis
    }
    !resource.is_empty() && resource.iter().all(|r| scope_permits(principal, Some(r)))
}

/// True iff the principal may act on a resource targeting `sites` x `environments`
/// — both axes must be contained within the principal's scope.
fn multi_scope_permits(session: &AuthSession, sites: &[String], environments: &[String]) -> bool {
    within_multi_scope(&session.site_scope, sites)
        && within_multi_scope(&session.environment_scope, environments)
}

/// Narrow a per-site aggregate JSON object to a principal's scope (#2). The rows
/// under `rows_key` are SITE-keyed (each has a "site" string) with no environment
/// dimension, so: unrestricted -> unchanged; site-scoped -> keep only in-scope
/// rows; environment-scoped -> none (an env scope cannot be honored on site-only
/// data, fail closed). Cross-site aggregate fields named in `drop_keys` are
/// removed for ANY scoped principal so they cannot leak out-of-scope totals.
fn narrow_site_aggregate(
    session: &AuthSession,
    value: &mut Value,
    rows_key: &str,
    drop_keys: &[&str],
) {
    use ryuki_engine::auth::scope_permits;
    let site_scoped = session.site_scope.iter().any(|s| !s.trim().is_empty());
    let env_scoped = session
        .environment_scope
        .iter()
        .any(|s| !s.trim().is_empty());
    if !site_scoped && !env_scoped {
        return; // unrestricted — see everything
    }
    if let Some(map) = value.as_object_mut() {
        if let Some(rows) = map.get_mut(rows_key).and_then(|v| v.as_array_mut()) {
            if env_scoped {
                rows.clear(); // site-keyed data cannot honor an environment scope
            } else {
                rows.retain(|row| {
                    row.get("site")
                        .and_then(|s| s.as_str())
                        .map(|s| scope_permits(&session.site_scope, Some(s)))
                        .unwrap_or(false)
                });
            }
        }
        for k in drop_keys {
            map.remove(*k);
        }
    }
}

/// Post-load guard for a multi-site/env resource: out-of-scope -> 404 (no
/// existence oracle), the multi-target analogue of `scope_guard_or_404`.
fn multi_scope_guard_or_404(
    session: &AuthSession,
    sites: &[String],
    environments: &[String],
    id: &str,
) -> Result<(), (StatusCode, Json<Value>)> {
    if multi_scope_permits(session, sites, environments) {
        Ok(())
    } else {
        Err(status_404(id))
    }
}

/// Load just `(site, environment)` for a request by id — for by-id scope guards
/// on endpoints that do not otherwise load the full row (e.g. the audit trail).
/// DB authoritative, else the in-memory store. `Ok(None)` ⇒ the request does not
/// exist. A DB error is PROPAGATED (not collapsed to `None`) so the caller can
/// fail CLOSED rather than serve data without a scope decision.
async fn request_site_env(request_id: &str) -> Result<Option<(String, String)>, sqlx::Error> {
    if let Some(pool) = get_db() {
        // A malformed id is "not found", not an error (mirrors the by-id 404s).
        let Ok(uid) = Uuid::parse_str(request_id) else {
            return Ok(None);
        };
        return sqlx::query_as::<_, (String, String)>(
            "SELECT site, environment FROM requests WHERE id = $1",
        )
        .bind(uid)
        .fetch_optional(pool)
        .await;
    }
    Ok(request_store()
        .lock()
        .await
        .iter()
        .find(|r| r.id == request_id)
        .map(|r| (r.site.clone(), r.environment.clone())))
}

async fn decommission_plan(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<DecommissionPlanRequest>,
) -> ApiResult {
    // A scoped principal may only plan a decommission for a site within its scope
    // (#2). The site is a caller-supplied body field, so a 403 (not a 404) is
    // correct here — there is no row to act as an existence oracle.
    guard_body_site_scope(&session, &body.site)?;
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let server_type = match body.server_type.as_str() {
        "VM" => ryuki_engine::models::ServerType::VM,
        "Physical" => ryuki_engine::models::ServerType::Physical,
        _ => return Err(status_400("Invalid server type. Use VM or Physical.")),
    };
    let mut req = server_decommission::plan_decommission(
        &body.server_name,
        &body.site,
        &body.os_family,
        server_type,
        &body.reason,
        body.final_backup_required,
        body.quarantine_days,
    )
    .map_err(|e| status_400(&e))?;

    // The engine generates a non-UUID id (e.g. "decom-abc12345") suitable for
    // in-memory use but not for the UUID primary key column. Replace it with a
    // proper UUID so the repo can bind it correctly.
    req.id = Uuid::new_v4().to_string();

    let mut tx = pool.begin().await.map_err(db_error)?;
    crate::repos::decommissions::insert(&mut *tx, &req)
        .await
        .map_err(db_error)?;
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "decommission-plan",
            None,
            "created",
            json!({
                "decommission_id": req.id,
                "server_name": req.server_name,
                "site": req.site,
            }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    Ok(Json(serde_json::to_value(&req).unwrap_or_default()))
}

async fn decommission_validate(Json(body): Json<DecommissionPlanRequest>) -> ApiResult {
    let server_type = match body.server_type.as_str() {
        "VM" => ryuki_engine::models::ServerType::VM,
        "Physical" => ryuki_engine::models::ServerType::Physical,
        _ => return Err(status_400("Invalid server type")),
    };
    let req = server_decommission::plan_decommission(
        &body.server_name,
        &body.site,
        &body.os_family,
        server_type,
        &body.reason,
        body.final_backup_required,
        body.quarantine_days,
    )
    .map_err(|e| status_400(&e))?;
    server_decommission::validate_decommission(&req)
        .map(|r| Json(serde_json::to_value(r).unwrap_or_default()))
        .map_err(|e| status_400(&e))
}

async fn decommission_approve(
    Path(id): Path<String>,
    Extension(session): Extension<AuthSession>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let req = crate::repos::decommissions::get(pool, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;

    // Scope guard BEFORE the engine state transition so an out-of-scope request
    // 404s exactly like a missing one — never a 409 oracle leaking its status (#2).
    site_scope_guard_or_404(&session, &req.site, &id)?;

    let before = crate::repos::decommissions::status_str(&req.status);

    // Approver = authenticated caller (from request extensions), never a
    // client-supplied body field — the audit trail must name the real principal.
    let approved = server_decommission::approve_decommission(&req, &session.user_id)
        .map_err(|e| status_409(&e))?;

    let mut tx = pool.begin().await.map_err(db_error)?;
    let ok = crate::repos::decommissions::transition(&mut tx, before, &approved, None)
        .await
        .map_err(db_error)?;
    if !ok {
        return Err(status_409("state changed concurrently; reload and retry"));
    }
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "decommission-approve",
            Some(before),
            "approved",
            json!({
                "decommission_id": approved.id,
                "server_name": approved.server_name,
                "site": approved.site,
            }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    Ok(Json(serde_json::to_value(&approved).unwrap_or_default()))
}

async fn decommission_quarantine(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let req = crate::repos::decommissions::get(pool, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;

    // Scope guard BEFORE the engine transition: out-of-scope 404s like a miss (#2).
    site_scope_guard_or_404(&session, &req.site, &id)?;

    let before = crate::repos::decommissions::status_str(&req.status);

    let quarantined = server_decommission::quarantine_server(&req).map_err(|e| status_409(&e))?;

    let mut tx = pool.begin().await.map_err(db_error)?;
    let ok =
        crate::repos::decommissions::transition(&mut tx, before, &quarantined, Some("quarantine"))
            .await
            .map_err(db_error)?;
    if !ok {
        return Err(status_409("state changed concurrently; reload and retry"));
    }
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "decommission-quarantine",
            Some(before),
            "quarantined",
            json!({
                "decommission_id": quarantined.id,
                "server_name": quarantined.server_name,
                "site": quarantined.site,
            }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    Ok(Json(serde_json::to_value(&quarantined).unwrap_or_default()))
}

