// ─── Linux Deployment handlers ───

fn parse_linux_distro(d: &str) -> ryuki_engine::models::LinuxDistro {
    match d {
        "sles" => ryuki_engine::models::LinuxDistro::Sles,
        "rhel" => ryuki_engine::models::LinuxDistro::Rhel,
        "rocky" => ryuki_engine::models::LinuxDistro::Rocky,
        "alma" => ryuki_engine::models::LinuxDistro::Alma,
        "ubuntu" => ryuki_engine::models::LinuxDistro::Ubuntu,
        "debian" => ryuki_engine::models::LinuxDistro::Debian,
        _ => ryuki_engine::models::LinuxDistro::Ubuntu,
    }
}

fn parse_hardening_profile(p: &str) -> ryuki_engine::models::HardeningProfile {
    match p {
        "cis-level-1" => ryuki_engine::models::HardeningProfile::CisLevel1,
        "cis-level-2" => ryuki_engine::models::HardeningProfile::CisLevel2,
        "stig" => ryuki_engine::models::HardeningProfile::Stig,
        "custom" => ryuki_engine::models::HardeningProfile::Custom,
        _ => ryuki_engine::models::HardeningProfile::CisLevel1,
    }
}

async fn linux_deploy_plan(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<LinuxDeployPlanRequest>,
) -> ApiResult {
    // A scoped principal may only plan a deployment for a site within its scope
    // (#2). Site is a caller-supplied body field, so a 403 (not 404) is correct —
    // no row exists yet to act as an existence oracle.
    guard_body_site_scope(&session, &body.site)?;
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let distro = parse_linux_distro(&body.distro);
    let hardening = parse_hardening_profile(&body.hardening_profile);

    let mut req = linux_deployment::plan_linux_deployment(
        distro,
        &body.version,
        &body.site,
        body.cpu,
        body.memory_gb,
        body.disk_gb,
        &body.hostname,
        &body.network,
        hardening,
    )
    .map_err(|e| status_400(&e))?;

    // The engine generates a non-UUID id (e.g. "ldep-abc12345") suitable for
    // in-memory use but not for the UUID primary key column. Replace it with a
    // proper UUID so the repo can bind it correctly.
    req.id = Uuid::new_v4().to_string();

    let mut tx = pool.begin().await.map_err(db_error)?;
    crate::repos::linux_deployment_requests::insert(&mut *tx, &req)
        .await
        .map_err(db_error)?;
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "linux-deploy-plan",
            None,
            "planned",
            json!({ "request_id": &req.id, "hostname": &req.hostname }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    Ok(Json(serde_json::to_value(&req).unwrap_or_default()))
}

async fn linux_deploy_validate(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<LinuxDeployActionRequest>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let req = crate::repos::linux_deployment_requests::get(pool, &body.operation_id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&body.operation_id))?;

    // Scope guard BEFORE the lifecycle 409 so an out-of-scope operation 404s like a
    // missing one — never a status oracle for a scoped principal (#2). Site-only.
    site_scope_guard_or_404(&session, &req.site, &body.operation_id)?;

    // Forward-only lifecycle (Planned -> Validated -> Executed -> Verified): the
    // engine does not enforce ordering, so the API does. Validate only from
    // Planned, never regressing a later state back to Validated.
    if req.status != ryuki_engine::models::LinuxDeploymentStatus::Planned {
        return Err(status_409("operation must be in Planned state to validate"));
    }

    let before = crate::repos::linux_deployment_requests::status_str(&req.status);

    let result = linux_deployment::validate_linux_deployment(&req).map_err(|e| status_409(&e))?;

    // Only ADVANCE to Validated when the check actually passed. A failed
    // validation leaves the operation in Planned so the caller can remediate and
    // re-validate; the failures travel back in the ValidationResult. (Recording a
    // failed validation as durable Validated would let it proceed to execute.)
    if result.passed {
        let mut validated_req = req;
        validated_req.status = ryuki_engine::models::LinuxDeploymentStatus::Validated;

        let mut tx = pool.begin().await.map_err(db_error)?;
        let ok =
            crate::repos::linux_deployment_requests::transition(&mut tx, before, &validated_req)
                .await
                .map_err(db_error)?;
        if !ok {
            return Err(status_409("state changed concurrently; reload and retry"));
        }
        audit::record_audit_tx(
            &mut tx,
            &session,
            &audit::security_audit(
                "linux-deploy-validate",
                Some(before),
                "validated",
                json!({ "request_id": &validated_req.id, "hostname": &validated_req.hostname }),
            ),
        )
        .await
        .map_err(db_error)?;
        tx.commit().await.map_err(db_error)?;
    }

    Ok(Json(serde_json::to_value(&result).unwrap_or_default()))
}

async fn linux_deploy_execute(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<LinuxDeployActionRequest>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let req = crate::repos::linux_deployment_requests::get(pool, &body.operation_id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&body.operation_id))?;

    // Scope guard BEFORE the lifecycle 409: out-of-scope 404s like a miss (#2).
    site_scope_guard_or_404(&session, &req.site, &body.operation_id)?;

    // Forward-only lifecycle: execute only from Validated. This enforces
    // validate-before-execute and prevents re-executing an already Executed or
    // Verified operation.
    if req.status != ryuki_engine::models::LinuxDeploymentStatus::Validated {
        return Err(status_409("operation must be Validated before execute"));
    }

    let before = crate::repos::linux_deployment_requests::status_str(&req.status);

    let executed = linux_deployment::execute_linux_deployment(&req).map_err(|e| status_409(&e))?;

    let mut tx = pool.begin().await.map_err(db_error)?;
    let ok = crate::repos::linux_deployment_requests::transition(&mut tx, before, &executed)
        .await
        .map_err(db_error)?;
    if !ok {
        return Err(status_409("state changed concurrently; reload and retry"));
    }
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "linux-deploy-execute",
            Some(before),
            "executed",
            json!({ "request_id": &executed.id, "hostname": &executed.hostname }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    Ok(Json(serde_json::to_value(&executed).unwrap_or_default()))
}

async fn linux_deploy_verify(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<LinuxDeployActionRequest>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let req = crate::repos::linux_deployment_requests::get(pool, &body.operation_id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&body.operation_id))?;

    // Scope guard BEFORE the lifecycle 409: out-of-scope 404s like a miss (#2).
    site_scope_guard_or_404(&session, &req.site, &body.operation_id)?;

    // Forward-only lifecycle: verify only from Executed.
    if req.status != ryuki_engine::models::LinuxDeploymentStatus::Executed {
        return Err(status_409("operation must be Executed before verify"));
    }

    let before = crate::repos::linux_deployment_requests::status_str(&req.status);

    let verification =
        linux_deployment::verify_linux_deployment(&req).map_err(|e| status_409(&e))?;

    // Persist `Verified` status after successful evidence collection.
    let mut verified_req = req;
    verified_req.status = ryuki_engine::models::LinuxDeploymentStatus::Verified;

    let mut tx = pool.begin().await.map_err(db_error)?;
    let ok = crate::repos::linux_deployment_requests::transition(&mut tx, before, &verified_req)
        .await
        .map_err(db_error)?;
    if !ok {
        return Err(status_409("state changed concurrently; reload and retry"));
    }
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "linux-deploy-verify",
            Some(before),
            "verified",
            json!({ "request_id": &verified_req.id, "hostname": &verified_req.hostname }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    Ok(Json(
        serde_json::to_value(&verification).unwrap_or_default(),
    ))
}

