async fn certificates_request(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<CertificateRequestRequest>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;
    // #2: a scoped principal may only request a certificate for its own site
    // (certificates are site-only — env-scoped principals are denied).
    guard_body_site_scope(&session, &body.site)?;

    let req = certificate_lifecycle::CertificateRequest {
        common_name: body.common_name,
        subject: body.subject,
        service_type: body.service_type,
        hostname: body.hostname,
        site: body.site,
        validity_days: body.validity_days,
    };

    let record = certificate_lifecycle::request_certificate(&req).map_err(|e| status_400(&e))?;

    // The engine already mints a valid UUID (Uuid::new_v4().to_string()), so no
    // id replacement is needed here (unlike engines that use human-readable ids).
    let mut tx = pool.begin().await.map_err(db_error)?;
    let persisted = crate::repos::certificates::insert(&mut *tx, &record)
        .await
        .map_err(db_error)?;
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "certificate-request",
            None,
            "requested",
            json!({
                "cert_id": persisted.id,
                "common_name": persisted.common_name,
                "site": persisted.site,
            }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    Ok(Json(serde_json::to_value(&persisted).unwrap_or_default()))
}

async fn certificates_validate(Json(body): Json<CertificateValidateRequest>) -> ApiResult {
    // Pure input validation — no DB interaction.
    let req = certificate_lifecycle::CertificateRequest {
        common_name: body.common_name,
        subject: body.subject,
        service_type: body.service_type,
        hostname: body.hostname,
        site: body.site,
        validity_days: body.validity_days,
    };
    match certificate_lifecycle::validate_certificate_request(&req) {
        Ok(()) => Ok(Json(
            serde_json::json!({"valid": true, "message": "Certificate request is valid"}),
        )),
        Err(e) => Err(status_400(&e)),
    }
}

async fn certificates_approve(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> ApiResult {
    // No state transition: CertificateStatus has no Approved variant.
    // This is an acknowledgement read — load and return the current record.
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let record = crate::repos::certificates::get(pool, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    // #2: certificates are site-only; guard on the loaded row's site (env-scoped
    // principals fail closed via the empty environment).
    scope_guard_or_404(&session, &record.site, "", &id)?;
    Ok(Json(serde_json::to_value(&record).unwrap_or_default()))
}

