async fn certificates_renew(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
    Json(body): Json<CertificateRenewRequest>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let cert = crate::repos::certificates::get(pool, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    // #2: certificates are site-only — guard on the loaded row's site.
    scope_guard_or_404(&session, &cert.site, "", &id)?;

    // A revoked certificate is a state conflict (409), not malformed input (400).
    if cert.status == certificate_lifecycle::CertificateStatus::Revoked {
        return Err(status_409("Cannot renew a revoked certificate"));
    }

    let before = crate::repos::certificates::status_str(&cert.status);

    // renew is a same-status transition (Active -> Active); the CAS guards on the
    // prior valid_to so two concurrent renews cannot both win.
    let renewed = certificate_lifecycle::renew_certificate(&cert, body.validity_days)
        .map_err(|e| status_400(&e))?;

    let mut tx = pool.begin().await.map_err(db_error)?;
    let persisted =
        crate::repos::certificates::transition(&mut *tx, before, &cert.valid_to, &renewed, None)
            .await
            .map_err(db_error)?
            .ok_or_else(|| status_409("state changed concurrently; reload and retry"))?;
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "certificate-renew",
            Some(before),
            "renewed",
            json!({
                "cert_id": cert.id,
                "common_name": cert.common_name,
                "site": cert.site,
            }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    Ok(Json(serde_json::to_value(&persisted).unwrap_or_default()))
}

async fn certificates_revoke(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let cert = crate::repos::certificates::get(pool, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    // #2: certificates are site-only — guard on the loaded row's site.
    scope_guard_or_404(&session, &cert.site, "", &id)?;

    let before = crate::repos::certificates::status_str(&cert.status);

    // Engine guard: returns Err if already revoked → 409.
    let revoked = certificate_lifecycle::revoke_certificate(&cert).map_err(|e| status_409(&e))?;

    let mut tx = pool.begin().await.map_err(db_error)?;
    let persisted =
        crate::repos::certificates::transition(&mut *tx, before, &cert.valid_to, &revoked, None)
            .await
            .map_err(db_error)?
            .ok_or_else(|| status_409("state changed concurrently; reload and retry"))?;
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "certificate-revoke",
            Some(before),
            "revoked",
            json!({
                "cert_id": cert.id,
                "common_name": cert.common_name,
                "site": cert.site,
            }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    Ok(Json(serde_json::to_value(&persisted).unwrap_or_default()))
}

async fn certificates_expiring(
    AuthExtractor(session): AuthExtractor,
    Query(query): Query<CertificateExpiringQuery>,
) -> ApiResult {
    // #2: scoped-site read ("" = all sites for an unrestricted caller).
    let site_scoped = enforce_site_scope(&session, query.site.as_deref(), "")?;
    let site = site_scoped.as_str();
    let days = query.days.unwrap_or(90);

    let Some(pool) = get_db() else {
        return Ok(Json(serde_json::Value::Array(vec![])));
    };

    let all = crate::repos::certificates::list(pool)
        .await
        .map_err(db_error)?;

    let results = certificate_lifecycle::check_expiry(&all, site, days);
    Ok(Json(serde_json::to_value(results).unwrap_or_default()))
}

async fn certificates_inventory(AuthExtractor(session): AuthExtractor) -> ApiResult {
    let Some(pool) = get_db() else {
        return Ok(Json(serde_json::Value::Array(vec![])));
    };
    let records = crate::repos::certificates::list(pool)
        .await
        .map_err(db_error)?;
    // #2: site-only — a scoped principal sees only its site's certs; an
    // environment-scoped principal sees none (retain_site_scoped fails closed).
    let records = retain_site_scoped(&session, records, |r| r.site.as_str());
    Ok(Json(serde_json::to_value(&records).unwrap_or_default()))
}

