struct ServicenowIncidentRequest {
    #[serde(rename = "ciName")]
    ci_name: String,
    description: String,
    urgency: String,
    #[serde(rename = "assignmentGroup")]
    assignment_group: String,
}

#[derive(Debug, Deserialize)]
