async fn servicenow_validate(Path(id): Path<String>) -> ApiResult {
    if let Some(pool) = get_db() {
        let uuid = parse_snow_id(&id)?;
        // Fetch current row to check status and validate required fields.
        let row: Option<ServiceNowRow> = sqlx::query_as(&format!(
            "SELECT {SNOW_COLUMNS} FROM servicenow_queue WHERE id = $1"
        ))
        .bind(uuid)
        .fetch_optional(pool)
        .await
        .map_err(db_error)?;
        let Some(row) = row else {
            return Err((
                StatusCode::NOT_FOUND,
                Json(json!({ "error": format!("ServiceNow request {} not found", id) })),
            ));
        };
        // Engine guards: must be Draft, ci_name and payload_summary non-empty.
        if row.status != "Draft" {
            return Err(status_400(&format!(
                "Request {} is not in Draft status (current: {})",
                id, row.status
            )));
        }
        if row.ci_name.is_empty() {
            return Err(status_400("ci_name is missing"));
        }
        if row.payload_summary.is_empty() {
            return Err(status_400("payload_summary is missing"));
        }
        return Ok(Json(json!({
            "id": row.id,
            "status": "validated",
            "passed": true,
            "errors": [],
            "warnings": ["DRY-RUN: static validation only — no live ServiceNow connectivity check"],
            "source": "database",
        })));
    }
    match servicenow_api::validate_request(&id) {
        Ok(result) => Ok(Json(result)),
        Err(e) if e.contains("not found") => {
            Err((StatusCode::NOT_FOUND, Json(json!({ "error": e }))))
        }
        Err(e) => Err(status_400(&e)),
    }
}

async fn servicenow_approve(Path(id): Path<String>) -> ApiResult {
    if let Some(pool) = get_db() {
        let uuid = parse_snow_id(&id)?;
        // Fetch row — engine reads the request to check guards but does NOT
        // mutate status (approve_request returns a response without writing to
        // the store). Mirror that: read-only guard check, no UPDATE.
        let row: Option<ServiceNowRow> = sqlx::query_as(&format!(
            "SELECT {SNOW_COLUMNS} FROM servicenow_queue WHERE id = $1"
        ))
        .bind(uuid)
        .fetch_optional(pool)
        .await
        .map_err(db_error)?;
        let Some(row) = row else {
            return Err((
                StatusCode::NOT_FOUND,
                Json(json!({ "error": format!("ServiceNow request {} not found", id) })),
            ));
        };
        // Engine guards: Submitted → error, Failed → error.
        if row.status == "Submitted" {
            return Err(status_400("Cannot approve — already submitted"));
        }
        if row.status == "Failed" {
            return Err(status_400("Cannot approve — request has failed"));
        }
        let now = chrono::Utc::now().to_rfc3339();
        return Ok(Json(json!({
            "id": row.id,
            "status": "approved",
            "approved_at": now,
            "source": "database",
            "note": "DRY-RUN: approval recorded locally — live ServiceNow API is pending approval",
        })));
    }
    match servicenow_api::approve_request(&id) {
        Ok(result) => Ok(Json(result)),
        Err(e) if e.contains("not found") => {
            Err((StatusCode::NOT_FOUND, Json(json!({ "error": e }))))
        }
        Err(e) => Err(status_400(&e)),
    }
}

async fn servicenow_submit(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> ApiResult {
    if let Some(pool) = get_db() {
        let uuid = parse_snow_id(&id)?;
        // Engine guards: Submitted → error, Failed → error.
        // Engine also gates Draft: if not Ready/Pending, it first sets status=Ready
        // then immediately sets status=Pending. Net effect: any non-Submitted
        // non-Failed status ends up as Pending. Use a conditional UPDATE that
        // rejects Submitted/Failed.
        let mut tx = pool.begin().await.map_err(db_error)?;
        let result = sqlx::query(
            "UPDATE servicenow_queue \
             SET status = 'Pending' \
             WHERE id = $1 AND status NOT IN ('Submitted', 'Failed')",
        )
        .bind(uuid)
        .execute(&mut *tx)
        .await
        .map_err(db_error)?;
        if result.rows_affected() == 1 {
            audit::record_audit_tx(
                &mut tx,
                &session,
                &audit::security_audit(
                    "servicenow-submit",
                    Some("queued"),
                    "submitted",
                    json!({ "queue_id": uuid.to_string() }),
                ),
            )
            .await
            .map_err(db_error)?;
            tx.commit().await.map_err(db_error)?;
            let now = chrono::Utc::now().to_rfc3339();
            return Ok(Json(json!({
                "id": uuid.to_string(),
                "status": "Pending",
                "queued_at": now,
                "source": "database",
                "note": "DRY-RUN: submission queued locally — live ServiceNow submission is disabled pending API approval",
            })));
        }
        // 0 rows affected: distinguish 404 vs wrong-state (400). Use pool (tx drops).
        let existing: Option<String> =
            sqlx::query_scalar("SELECT status FROM servicenow_queue WHERE id = $1")
                .bind(uuid)
                .fetch_optional(pool)
                .await
                .map_err(db_error)?;
        return match existing {
            None => Err((
                StatusCode::NOT_FOUND,
                Json(json!({ "error": format!("ServiceNow request {} not found", id) })),
            )),
            Some(s) if s == "Submitted" => Err(status_400("Already submitted")),
            Some(_) => Err(status_400("Cannot queue — request has failed")),
        };
    }
    match servicenow_api::queue_for_submission(&id) {
        Ok(result) => Ok(Json(result)),
        Err(e) if e.contains("not found") => {
            Err((StatusCode::NOT_FOUND, Json(json!({ "error": e }))))
        }
        Err(e) => Err(status_400(&e)),
    }
}

async fn servicenow_status(Path(id): Path<String>) -> ApiResult {
    if let Some(pool) = get_db() {
        let uuid = parse_snow_id(&id)?;
        let row: Option<ServiceNowRow> = sqlx::query_as(&format!(
            "SELECT {SNOW_COLUMNS} FROM servicenow_queue WHERE id = $1"
        ))
        .bind(uuid)
        .fetch_optional(pool)
        .await
        .map_err(db_error)?;
        return match row {
            Some(r) => Ok(Json(snow_row_to_status_json(&r))),
            None => Err((
                StatusCode::NOT_FOUND,
                Json(json!({ "error": format!("ServiceNow request {} not found", id) })),
            )),
        };
    }
    match servicenow_api::get_submission_status(&id) {
        Ok(result) => Ok(Json(result)),
        Err(e) => Err(status_404(&e)),
    }
}

async fn servicenow_pending() -> ApiResult {
    if let Some(pool) = get_db() {
        let rows: Vec<ServiceNowRow> = sqlx::query_as(&format!(
            "SELECT {SNOW_COLUMNS} FROM servicenow_queue \
             WHERE status IN ('Pending', 'Ready') ORDER BY created_at"
        ))
        .fetch_all(pool)
        .await
        .map_err(db_error)?;
        let items: Vec<Value> = rows.iter().map(snow_row_to_summary_json).collect();
        return Ok(Json(json!({
            "source": "database",
            "count": items.len(),
            "items": items,
        })));
    }
    Ok(Json(servicenow_api::get_pending_submissions()))
}

async fn servicenow_cancel(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> ApiResult {
    if let Some(pool) = get_db() {
        let uuid = parse_snow_id(&id)?;
        // Engine guard: Submitted → error. Unconditional set to Failed otherwise.
        let mut tx = pool.begin().await.map_err(db_error)?;
        let result = sqlx::query(
            "UPDATE servicenow_queue \
             SET status = 'Failed' \
             WHERE id = $1 AND status <> 'Submitted'",
        )
        .bind(uuid)
        .execute(&mut *tx)
        .await
        .map_err(db_error)?;
        if result.rows_affected() == 1 {
            audit::record_audit_tx(
                &mut tx,
                &session,
                &audit::security_audit(
                    "servicenow-cancel",
                    None,
                    "cancelled",
                    json!({ "queue_id": uuid.to_string() }),
                ),
            )
            .await
            .map_err(db_error)?;
            tx.commit().await.map_err(db_error)?;
            return Ok(Json(json!({
                "id": uuid.to_string(),
                "status": "cancelled",
                "cancelled_at": chrono::Utc::now().to_rfc3339(),
                "source": "database",
            })));
        }
        // 0 rows: distinguish 404 vs wrong-state (Submitted → 400). Use pool (tx drops).
        let existing: Option<String> =
            sqlx::query_scalar("SELECT status FROM servicenow_queue WHERE id = $1")
                .bind(uuid)
                .fetch_optional(pool)
                .await
                .map_err(db_error)?;
        return match existing {
            None => Err((
                StatusCode::NOT_FOUND,
                Json(json!({ "error": format!("ServiceNow request {} not found", id) })),
            )),
            Some(_) => Err(status_400(
                "Cannot cancel — request has already been submitted",
            )),
        };
    }
    match servicenow_api::cancel_request(&id) {
        Ok(result) => Ok(Json(result)),
        Err(e) if e.contains("not found") => {
            Err((StatusCode::NOT_FOUND, Json(json!({ "error": e }))))
        }
        Err(e) => Err(status_400(&e)),
    }
}

async fn servicenow_history(Path(ci): Path<String>) -> ApiResult {
    if let Some(pool) = get_db() {
        let rows: Vec<ServiceNowRow> = sqlx::query_as(&format!(
            "SELECT {SNOW_COLUMNS} FROM servicenow_queue \
             WHERE ci_name = $1 ORDER BY created_at"
        ))
        .bind(&ci)
        .fetch_all(pool)
        .await
        .map_err(db_error)?;
        let entries: Vec<Value> = rows.iter().map(snow_row_to_history_json).collect();
        return Ok(Json(json!({
            "source": "database",
            "ci_name": ci,
            "count": entries.len(),
            "items": entries,
        })));
    }
    Ok(Json(servicenow_api::get_submission_history(&ci)))
}

async fn servicenow_contract() -> Json<Value> {
    Json(servicenow_api::get_snow_contract())
}

// ─── Repository Capacity Forecasting ───

#[derive(Deserialize)]
struct RepoCapacitySiteQuery {
    site: Option<String>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct RepoCapacityUpdateBody {
    // The API/response field is `used_capacity_tb`; accept the legacy `used_tb`
    // key too so existing callers keep working. (`alias` is a KNOWN field name, so
    // deny_unknown_fields still accepts it — it only rejects truly-unknown keys.)
    #[serde(alias = "used_tb")]
    used_capacity_tb: Option<f64>,
}

#[derive(Deserialize)]
struct RepoCapacityForecastQuery {
    days: Option<u32>,
}

#[derive(Deserialize)]
struct RepoCapacityTrendQuery {
    months: Option<u32>,
}

async fn repo_capacity_list(
    AuthExtractor(session): AuthExtractor,
    Query(params): Query<RepoCapacitySiteQuery>,
) -> ApiResult {
    // #2: scoped-site read (default DEFRA for an unrestricted caller).
    let site_scoped = enforce_site_scope(&session, params.site.as_deref(), "DEFRA")?;
    let site = site_scoped.as_str();
    let repos = match get_db() {
        Some(pool) => crate::repos::repository_capacity::list_by_site(pool, site)
            .await
            .map_err(db_error)?,
        None => Vec::new(),
    };
    Ok(Json(repository_capacity::get_repositories(&repos, site)))
}

/// GET /api/protect/repository-capacity/{id} — one repository's current capacity.
/// Mirrors the by-id READ pattern of `repo_capacity_forecast`: load → 404 if absent
/// → `site_scope_guard_or_404` (an out-of-scope repo 404s like a missing one, no
/// existence oracle). The projection matches `repo_capacity_update`'s single-repo
/// view. No-DB resolves to None ⇒ 404 (read consistency, not the update's 503).
async fn repo_capacity_get(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> ApiResult {
    let repo = match get_db() {
        Some(pool) => crate::repos::repository_capacity::get(pool, &id)
            .await
            .map_err(db_error)?,
        None => None,
    }
    .ok_or_else(|| status_404(&id))?;
    site_scope_guard_or_404(&session, &repo.site, &id)?;
    Ok(Json(json!({
        "repository_id": repo.id,
        "name": repo.name,
        "used_capacity_tb": repo.used_capacity_tb,
        "days_until_full": repository_capacity::repo_days(&repo),
        "status": repository_capacity::repo_status(&repo),
        "last_forecast": repo.last_forecast,
    })))
}

async fn repo_capacity_update(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
    Json(body): Json<RepoCapacityUpdateBody>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;
    // used_capacity_tb is required: defaulting a missing value to 0.0 would
    // durably zero a repository's usage on an empty/partial body.
    let used_tb = match body.used_capacity_tb {
        Some(v) if v.is_finite() && v >= 0.0 => v,
        Some(_) => {
            return Err(status_400(
                "used_capacity_tb must be a finite, non-negative number",
            ));
        }
        None => return Err(status_400("used_capacity_tb is required")),
    };

    // Load the repository first so we can validate it exists and recompute
    // derived fields using the engine before persisting.
    let repo = crate::repos::repository_capacity::get(pool, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    // #2: a scoped principal may only update a repository in its own site. The
    // authoritative re-check is the `AND site = $N` predicate in update_usage
    // below, so a concurrent re-home cannot slip an out-of-scope write through;
    // this is the fast pre-check on the loaded row.
    guard_body_site_scope(&session, &repo.site)?;
    let repo_site = repo.site.clone();

    // Build an updated model with the new usage so the engine can recompute
    // days_until_full and status from the authoritative (total, used, growth).
    let updated = ryuki_engine::repository_capacity::Repository {
        used_capacity_tb: used_tb,
        ..repo
    };
    let new_days = repository_capacity::repo_days(&updated);
    let new_status = repository_capacity::repo_status(&updated);
    let new_status_str = crate::repos::repository_capacity::capacity_status_str(&new_status);

    let mut tx = pool.begin().await.map_err(db_error)?;
    let persisted = crate::repos::repository_capacity::update_usage(
        &mut *tx,
        &id,
        used_tb,
        new_days,
        new_status_str,
        &repo_site,
    )
    .await
    .map_err(db_error)?
    .ok_or_else(|| status_404(&id))?;
    crate::audit::record_audit_tx(
        &mut tx,
        &session,
        &crate::audit::security_audit(
            "repo-capacity-update",
            None,
            "updated",
            json!({ "repo_id": &id, "site": &repo_site }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;

    Ok(Json(json!({
        "repository_id": persisted.id,
        "name": persisted.name,
        "used_capacity_tb": persisted.used_capacity_tb,
        "days_until_full": repository_capacity::repo_days(&persisted),
        "status": repository_capacity::repo_status(&persisted),
        "last_forecast": persisted.last_forecast,
    })))
}

async fn repo_capacity_forecast(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
    Query(params): Query<RepoCapacityForecastQuery>,
) -> ApiResult {
    let days = params.days.unwrap_or(30);
    let repos = match get_db() {
        Some(pool) => match crate::repos::repository_capacity::get(pool, &id)
            .await
            .map_err(db_error)?
        {
            // #2: a scoped principal may only read a repo in its own site — an
            // out-of-scope repo 404s like a missing one (site-only resource).
            Some(r) => {
                site_scope_guard_or_404(&session, &r.site, &id)?;
                vec![r]
            }
            None => Vec::new(),
        },
        None => Vec::new(),
    };
    match repository_capacity::forecast_capacity(&repos, &id, days) {
        Some(v) => Ok(Json(v)),
        None => Err(status_404(&id)),
    }
}

