// ─── Image factory handlers ───

#[derive(Deserialize)]
struct ImageFactoryBuildBody {
    image_name: String,
    os_family: String,
    distro: String,
    version: String,
    site: String,
}

#[derive(Deserialize)]
struct ImageFactoryRejectBody {
    reason: String,
}

#[derive(Deserialize)]
struct ImageFactoryScheduleBody {
    site: String,
    os_family: String,
    distro: String,
}

async fn image_factory_initiate_build(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<ImageFactoryBuildBody>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;
    // #2: scoped principals may only initiate a build for their own site;
    // env-scoped principals are rejected (golden_images is site-only).
    guard_body_site_scope(&session, &body.site)?;

    let img = image_factory::initiate_build(
        &body.image_name,
        &body.os_family,
        &body.distro,
        &body.version,
        &body.site,
    )
    .map_err(|e| status_400(&e))?;

    let persisted = crate::repos::golden_images::insert(pool, &img)
        .await
        .map_err(|e| {
            if let Some(d) = e.as_database_error() {
                if d.is_unique_violation()
                    && d.constraint() == Some("golden_images_image_name_site_scope_key")
                {
                    return status_409("an image with that name already exists in this scope");
                }
            }
            db_error(e)
        })?;

    Ok(Json(serde_json::to_value(&persisted).unwrap_or_default()))
}

async fn image_factory_run_tests(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let img = crate::repos::golden_images::get(pool, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    // #2: out-of-scope -> 404 before the transition/status-409 leak.
    scope_guard_or_404(&session, &img.site_scope, "", &id)?;

    let before = crate::repos::golden_images::status_str(&img.status);
    let testing = image_factory::run_tests(&img).map_err(|e| status_409(&e))?;

    let persisted = crate::repos::golden_images::transition(pool, before, &testing)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_409("state changed concurrently; reload and retry"))?;

    Ok(Json(serde_json::to_value(&persisted).unwrap_or_default()))
}

async fn image_factory_promote(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let img = crate::repos::golden_images::get(pool, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    // #2: out-of-scope -> 404 before the promote/status-409 leak.
    scope_guard_or_404(&session, &img.site_scope, "", &id)?;

    let promoted = image_factory::promote_image(&img).map_err(|e| status_409(&e))?;

    let (persisted, superseded_ids) = crate::repos::golden_images::promote(pool, &promoted)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_409("state changed concurrently; reload and retry"))?;

    Ok(Json(json!({
        "image": serde_json::to_value(&persisted).unwrap_or_default(),
        "superseded": superseded_ids,
    })))
}

async fn image_factory_reject(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
    Json(body): Json<ImageFactoryRejectBody>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;

    let img = crate::repos::golden_images::get(pool, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    // #2: out-of-scope -> 404 before the reject/status-409 leak.
    scope_guard_or_404(&session, &img.site_scope, "", &id)?;

    let before = crate::repos::golden_images::status_str(&img.status);
    let failed = image_factory::reject_image(&img, &body.reason).map_err(|e| status_409(&e))?;

    let persisted = crate::repos::golden_images::transition(pool, before, &failed)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_409("state changed concurrently; reload and retry"))?;

    Ok(Json(serde_json::to_value(&persisted).unwrap_or_default()))
}

async fn image_factory_active(
    AuthExtractor(session): AuthExtractor,
    Path(site): Path<String>,
) -> ApiResult {
    // #2: scoped principals may only list active images for their own site.
    guard_body_site_scope(&session, &site)?;
    // Graceful degradation: no DB → empty list (not a 503)
    if let Some(pool) = get_db() {
        let images = crate::repos::golden_images::list_promoted(pool, &site)
            .await
            .map_err(db_error)?;

        let mut by_os: std::collections::HashMap<String, Vec<serde_json::Value>> =
            std::collections::HashMap::new();
        for img in &images {
            by_os
                .entry(img.os_family.clone())
                .or_default()
                .push(serde_json::to_value(img).unwrap_or_default());
        }

        return Ok(Json(json!({
            "site": site,
            "active_count": images.len(),
            "active_by_os": by_os,
        })));
    }
    Ok(Json(json!({
        "site": site,
        "active_count": 0,
        "active_by_os": {},
    })))
}

