async fn evidence_redact(
    Json(body): Json<EvidenceRedactRequest>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let mut pack: ryuki_engine::models::EvidencePack =
        serde_json::from_value(body.pack).map_err(|e| {
            (
                StatusCode::BAD_REQUEST,
                Json(json!({"error": e.to_string()})),
            )
        })?;
    evidence_pipeline::redact_evidence(&mut pack)
        .map(|_| Json(serde_json::to_value(&pack).unwrap_or_default()))
        .map_err(|e| (StatusCode::BAD_REQUEST, Json(json!({"error": e}))))
}

async fn evidence_export(
    Query(params): Query<EvidenceExportQuery>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let req = ryuki_engine::models::Request::new(
        "req-evidence-export".into(),
        "offering-vm".into(),
        ryuki_engine::models::RequestType::ServerDeployment,
        "system-engineer".into(),
        "app-team-web".into(),
        "DEFRA".into(),
        "production".into(),
        "high".into(),
    );
    let pack = evidence_pipeline::collect_evidence(&req)
        .map_err(|e| (StatusCode::BAD_REQUEST, Json(json!({"error": e}))))?;
    let format_str = params.format.as_deref().unwrap_or("json");
    evidence_pipeline::export_evidence(&pack, format_str)
        .map(|data| Json(json!({"source": "dry-run", "format": format_str, "data": data})))
        .map_err(|e| (StatusCode::BAD_REQUEST, Json(json!({"error": e}))))
}

async fn evidence_verify_compliance(
    Json(body): Json<EvidenceRedactRequest>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let pack: ryuki_engine::models::EvidencePack =
        serde_json::from_value(body.pack).map_err(|e| {
            (
                StatusCode::BAD_REQUEST,
                Json(json!({"error": e.to_string()})),
            )
        })?;
    evidence_pipeline::verify_evidence_compliance(&pack)
        .map(|issues| {
            Json(json!({"source": "dry-run", "compliant": issues.is_empty(), "issues": issues}))
        })
        .map_err(|e| (StatusCode::BAD_REQUEST, Json(json!({"error": e}))))
}

// ─── Health Monitor handlers ───

/// GET /api/platform/health/all — component health checks. These are SIMULATED
/// (the health_monitor engine is pure / IO-free), so the overall status is NOT a
/// live truth signal. The response is marked `advisory` and points at the real
/// dependency-backed probe (#6) so a monitoring system can never mistake a
/// hardcoded `healthy` for a live one (swarm finding #4). Additive: the original
/// PlatformHealth fields are unchanged.
async fn platform_health_all_checks() -> Json<Value> {
    let health = health_monitor::run_all_checks();
    let mut body = serde_json::to_value(&health).unwrap_or_else(|_| json!({}));
    if let Value::Object(ref mut m) = body {
        m.insert("advisory".into(), json!(true));
        m.insert(
            "note".into(),
            json!(
                "Component checks are SIMULATED (dry-run posture), NOT live probes — \
                 not authoritative for alerting. For real dependency health use \
                 GET /api/platform/health/dependencies."
            ),
        );
        m.insert(
            "authoritative_endpoint".into(),
            json!("/api/platform/health/dependencies"),
        );
    }
    Json(body)
}

async fn platform_health_check_adapter(
    Path(adapter): Path<String>,
) -> Json<ryuki_engine::health_monitor::HealthCheck> {
    Json(health_monitor::check_adapter_health(&adapter))
}

async fn platform_health_metrics_text() -> axum::response::Response {
    // Dependency-backed: the db component of the `ryuki_platform_health` gauge
    // reflects a real connectivity probe rather than the simulated placeholder.
    let health = crate::database::live_platform_health().await;
    let body = health_monitor::metrics_text_from_health(&health, 0);
    axum::response::Response::builder()
        .header("Content-Type", "text/plain; charset=utf-8")
        .body(axum::body::Body::from(body))
        .unwrap()
}

