async fn firmware_request_exception(
    Extension(session): Extension<AuthSession>,
    Json(body): Json<FirmwareExceptionRequest>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    // approved_by = authenticated caller (from request extensions), never a client
    // body field — the exception's approval must name the real principal.
    // Pure validation first (engine guard).
    firmware_lifecycle::validate_exception_request(
        &body.reason,
        &session.user_id,
        body.expiry_days,
    )
    .map_err(|e| status_400(&e))?;
    let pool = get_db().ok_or_else(status_503_no_db)?;
    // #2: scope on the target device's site before creating an exception for it;
    // an out-of-scope or missing device -> 404 (no existence oracle).
    let device = crate::repos::firmware_lifecycle::get_device(pool, &body.device_id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&body.device_id))?;
    scope_guard_or_404(&session, &device.site, "", &body.device_id)?;
    let exception = crate::repos::firmware_lifecycle::request_exception(
        pool,
        &body.device_id,
        &body.reason,
        &session.user_id,
        body.expiry_days,
    )
    .await
    .map_err(db_error)?
    .ok_or_else(|| status_404(&body.device_id))?;
    Ok(Json(json!({
        "source": "live",
        "exception": exception,
        "device_status": firmware_lifecycle::ComplianceStatus::Exception.to_string()
    })))
}

async fn firmware_exceptions_list(
    AuthExtractor(session): AuthExtractor,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    match get_db() {
        Some(pool) => {
            let mut exceptions = crate::repos::firmware_lifecycle::list_active_exceptions(pool)
                .await
                .map_err(db_error)?;
            // #2: firmware_exceptions has no site column — retain only those whose
            // parent device is in the principal's scope (resolved via a device map;
            // env-scoped principals keep none).
            if is_scoped(&session) {
                let devices = crate::repos::firmware_lifecycle::list_all_for_report(pool)
                    .await
                    .map_err(db_error)?;
                let in_scope: std::collections::HashSet<String> = devices
                    .iter()
                    .filter(|d| row_scope_permits(&session, &d.site, ""))
                    .map(|d| d.id.clone())
                    .collect();
                exceptions.retain(|e| in_scope.contains(&e.device_id));
            }
            Ok(Json(json!({
                "source": "live",
                "count": exceptions.len(),
                "exceptions": exceptions
            })))
        }
        None => Ok(Json(
            json!({ "source": "dry-run", "count": 0, "exceptions": [] }),
        )),
    }
}

async fn firmware_revoke_exception(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let pool = get_db().ok_or_else(status_503_no_db)?;
    // #2: scope on the exception's parent-device site (join) BEFORE revoking; an
    // out-of-scope or missing exception -> 404 (no oracle, no cross-site revoke).
    if is_scoped(&session) {
        let site: Option<String> = sqlx::query_scalar(
            "SELECT fr.site FROM firmware_exceptions fe \
             JOIN firmware_records fr ON fe.device_id = fr.id WHERE fe.id = $1",
        )
        .bind(&id)
        .fetch_optional(pool)
        .await
        .map_err(db_error)?;
        if !site
            .map(|s| row_scope_permits(&session, &s, ""))
            .unwrap_or(false)
        {
            return Err(status_404(&id));
        }
    }
    let device_id = crate::repos::firmware_lifecycle::revoke_exception(pool, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&id))?;
    Ok(Json(json!({
        "source": "live",
        "revoked_exception_id": id,
        "device_id": device_id,
        "device_status": firmware_lifecycle::ComplianceStatus::NonCompliant.to_string()
    })))
}

async fn firmware_compliance_report(
    AuthExtractor(session): AuthExtractor,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    match get_db() {
        Some(pool) => {
            let devices = crate::repos::firmware_lifecycle::list_all_for_report(pool)
                .await
                .map_err(db_error)?;
            // #2: a scoped principal's report counts only its own site's devices.
            let devices = retain_site_scoped(&session, devices, |d| d.site.as_str());
            let total = devices.len();
            let compliant = devices
                .iter()
                .filter(|d| d.compliance_status == firmware_lifecycle::ComplianceStatus::Compliant)
                .count();
            let noncompliant = devices
                .iter()
                .filter(|d| {
                    d.compliance_status == firmware_lifecycle::ComplianceStatus::NonCompliant
                })
                .count();
            let eol = devices
                .iter()
                .filter(|d| d.compliance_status == firmware_lifecycle::ComplianceStatus::EOL)
                .count();
            let exception = devices
                .iter()
                .filter(|d| d.compliance_status == firmware_lifecycle::ComplianceStatus::Exception)
                .count();
            Ok(Json(json!({
                "source": "live",
                "total": total,
                "compliant": compliant,
                "noncompliant": noncompliant,
                "eol": eol,
                "exception": exception,
            })))
        }
        None => Ok(Json(json!({
            "source": "dry-run",
            "total": 0,
            "compliant": 0,
            "noncompliant": 0,
            "eol": 0,
            "exception": 0,
            "dry_run": true
        }))),
    }
}

async fn firmware_vendor_summary(
    AuthExtractor(session): AuthExtractor,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    match get_db() {
        Some(pool) => {
            let devices = crate::repos::firmware_lifecycle::list_all_for_report(pool)
                .await
                .map_err(db_error)?;
            // #2: a scoped principal's vendor summary covers only its own site's devices.
            let devices = retain_site_scoped(&session, devices, |d| d.site.as_str());
            let mut vendors: std::collections::BTreeMap<
                String,
                (usize, usize, usize, usize, usize),
            > = std::collections::BTreeMap::new();
            for device in &devices {
                let entry = vendors
                    .entry(device.vendor.clone())
                    .or_insert((0, 0, 0, 0, 0));
                entry.0 += 1;
                match device.compliance_status {
                    firmware_lifecycle::ComplianceStatus::Compliant => entry.1 += 1,
                    firmware_lifecycle::ComplianceStatus::NonCompliant => entry.2 += 1,
                    firmware_lifecycle::ComplianceStatus::EOL => entry.3 += 1,
                    firmware_lifecycle::ComplianceStatus::Exception => entry.4 += 1,
                }
            }
            let summary: Vec<Value> = vendors
                .into_iter()
                .map(
                    |(vendor, (total, compliant, noncompliant, eol, exception))| {
                        let pct = if total == 0 {
                            0.0
                        } else {
                            (compliant as f64 / total as f64) * 100.0
                        };
                        json!({
                            "vendor": vendor,
                            "total": total,
                            "compliant": compliant,
                            "noncompliant": noncompliant,
                            "eol": eol,
                            "exception": exception,
                            "compliance_percentage": pct
                        })
                    },
                )
                .collect();
            Ok(Json(json!({ "source": "live", "vendors": summary })))
        }
        None => Ok(Json(json!({ "source": "dry-run", "vendors": [] }))),
    }
}

