async fn access_review_summary(AuthExtractor(session): AuthExtractor) -> ApiResult {
    match get_db() {
        Some(pool) => {
            // #2: the repo summary aggregates EVERY site. A scoped principal gets a
            // summary recomputed from ONLY its own site's reviews (env-scoped -> 403
            // via enforce_site_scope); an unrestricted caller keeps the global one.
            if is_scoped(&session) {
                let site = enforce_site_scope(&session, None, "")?;
                let reviews = crate::repos::access_recertification::list(pool, &site, "")
                    .await
                    .map_err(db_error)?;
                use access_recertification::ReviewStatus;
                let n = |s: ReviewStatus| reviews.iter().filter(|r| r.status == s).count();
                return Ok(Json(serde_json::json!({
                    "source": "scoped",
                    "site": site,
                    "total": reviews.len(),
                    "pending": n(ReviewStatus::Pending),
                    "in_progress": n(ReviewStatus::InProgress),
                    "approved": n(ReviewStatus::Approved),
                    "revoked": n(ReviewStatus::Revoked),
                    "exempted": n(ReviewStatus::Exempted),
                })));
            }
            let val = crate::repos::access_recertification::summary(pool)
                .await
                .map_err(db_error)?;
            Ok(Json(val))
        }
        None => Ok(Json(serde_json::json!({
            "source": "empty",
            "total": 0,
            "pending": 0,
            "in_progress": 0,
            "approved": 0,
            "revoked": 0,
            "exempted": 0
        }))),
    }
}

async fn access_campaign_create(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<AccessCampaignCreateRequest>,
) -> ApiResult {
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let review_type =
        access_recertification::parse_review_type(&body.review_type).map_err(|e| status_400(&e))?;
    access_recertification::create_campaign_guard(&body.name, &body.reviewer_group, body.days)
        .map_err(|e| status_400(&e))?;
    let campaign = access_recertification::build_campaign(
        &body.name,
        review_type,
        &body.reviewer_group,
        body.days,
        0, // overwritten by insert_campaign DB count
        0,
    );
    let mut tx = pool.begin().await.map_err(db_error)?;
    let inserted = crate::repos::access_recertification::insert_campaign(&mut tx, &campaign)
        .await
        .map_err(db_error)?;
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "access-campaign-create",
            None,
            "created",
            json!({ "campaign_id": &inserted.id, "campaign_name": &inserted.name }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;
    Ok(Json(access_recertification::campaign_response(&inserted)))
}

