async fn compliance_control_get(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
) -> ApiResult {
    let Some(pool) = get_db() else {
        return Err((
            StatusCode::NOT_FOUND,
            Json(json!({"error": format!("Compliance control '{}' not found", id)})),
        ));
    };
    let ctrl = crate::repos::compliance_reporting::get_control(pool, &id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| {
            (
                StatusCode::NOT_FOUND,
                Json(json!({"error": format!("Compliance control '{}' not found", id)})),
            )
        })?;
    // #2: an out-of-scope control is reported identically to a missing one (the
    // handler's own 404 body) so a scoped principal gets no existence oracle.
    if !row_scope_permits(&session, &ctrl.site, "") {
        return Err((
            StatusCode::NOT_FOUND,
            Json(json!({"error": format!("Compliance control '{}' not found", id)})),
        ));
    }
    Ok(Json(json!({ "source": "db", "control": ctrl })))
}

async fn compliance_control_assess(
    Path(id): Path<String>,
    Extension(session): Extension<AuthSession>,
    Json(b): Json<ComplianceAssessRequest>,
) -> ApiResult {
    // actor = authenticated caller (from request extensions), never a client
    // body field — the audit trail must name the real principal.
    if b.evidence_ref.trim().is_empty() {
        return Err(status_400("evidence_ref cannot be empty"));
    }
    let status =
        compliance_reporting::parse_control_status(&b.status).map_err(|e| status_400(&e))?;

    let pool = get_db().ok_or_else(status_503_no_db)?;
    // #2: scope on the control's site BEFORE the assessment write; an out-of-scope
    // or missing control is reported as the same not-found (no oracle, no
    // cross-site assess).
    match crate::repos::compliance_reporting::get_control(pool, &id)
        .await
        .map_err(db_error)?
    {
        Some(ref c) if row_scope_permits(&session, &c.site, "") => {}
        _ => {
            return Err((
                StatusCode::NOT_FOUND,
                Json(json!({"error": format!("Compliance control '{}' not found", id)})),
            ));
        }
    }
    use crate::repos::compliance_reporting::AssessOutcome;
    match crate::repos::compliance_reporting::assess_control(
        pool,
        &id,
        &status,
        &session.user_id,
        &b.evidence_ref,
    )
    .await
    .map_err(db_error)?
    {
        AssessOutcome::Updated(ctrl) => Ok(Json(json!({ "source": "db", "control": ctrl }))),
        AssessOutcome::NotFound => Err((
            StatusCode::NOT_FOUND,
            Json(json!({"error": format!("Compliance control '{}' not found", id)})),
        )),
    }
}

async fn compliance_report_generate(
    AuthExtractor(session): AuthExtractor,
    Json(b): Json<ComplianceReportGenerateRequest>,
) -> ApiResult {
    // #2: a scoped principal may only generate a compliance report for its site.
    guard_body_site_scope(&session, &b.site)?;
    if b.site.trim().is_empty() {
        return Err(status_400("site cannot be empty"));
    }
    if b.framework_id.trim().is_empty() {
        return Err(status_400("framework_id cannot be empty"));
    }

    let pool = get_db().ok_or_else(status_503_no_db)?;

    // Verify framework exists
    crate::repos::compliance_reporting::get_framework(pool, &b.framework_id)
        .await
        .map_err(db_error)?
        .ok_or_else(|| {
            (
                StatusCode::NOT_FOUND,
                Json(
                    json!({"error": format!("Compliance framework '{}' not found", b.framework_id)}),
                ),
            )
        })?;

    // Load controls for this framework+site
    let controls =
        crate::repos::compliance_reporting::list_controls(pool, &b.framework_id, &b.site)
            .await
            .map_err(db_error)?;
    if controls.is_empty() {
        return Err(status_400(&format!(
            "No controls found for framework '{}' at site '{}'",
            b.framework_id, b.site
        )));
    }

    let report = crate::repos::compliance_reporting::generate_report(
        pool,
        &b.framework_id,
        &b.site,
        &controls,
    )
    .await
    .map_err(db_error)?;
    Ok(Json(json!({ "source": "db", "report": report })))
}

