async fn compliance_finding_resolve(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
    Json(b): Json<ComplianceResolveRequest>,
) -> ApiResult {
    if b.resolution.trim().is_empty() {
        return Err(status_400("resolution cannot be empty"));
    }
    let pool = get_db().ok_or_else(status_503_no_db)?;
    // #2: compliance_findings has no site column — scope on the parent report's
    // site (join). An out-of-scope or missing finding -> the same 404 "Finding not
    // found" before the resolve write (no oracle, no cross-site resolve).
    if is_scoped(&session) {
        let site: Option<String> = sqlx::query_scalar(
            "SELECT cr.site FROM compliance_findings cf \
             JOIN compliance_reports cr ON cf.report_id = cr.id WHERE cf.id = $1",
        )
        .bind(&id)
        .fetch_optional(pool)
        .await
        .map_err(db_error)?;
        if !site
            .map(|s| row_scope_permits(&session, &s, ""))
            .unwrap_or(false)
        {
            return Err((
                StatusCode::NOT_FOUND,
                Json(json!({"error": format!("Finding '{}' not found", id)})),
            ));
        }
    }
    use crate::repos::compliance_reporting::MutationOutcome;
    let mut tx = pool.begin().await.map_err(db_error)?;
    let outcome = crate::repos::compliance_reporting::resolve_finding(&mut *tx, &id, &b.resolution)
        .await
        .map_err(db_error)?;
    let MutationOutcome::Updated(ref f) = outcome else {
        return Err((
            StatusCode::NOT_FOUND,
            Json(json!({"error": format!("Finding '{}' not found", id)})),
        ));
    };
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "compliance-finding-resolve",
            // The UPDATE has no status guard and we don't read the prior state,
            // so we don't claim a from_status (avoids mis-recording a re-resolve).
            None,
            "resolved",
            json!({ "finding_id": &id }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;
    Ok(Json(json!({ "source": "db", "finding": f })))
}

async fn compliance_finding_waive(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<String>,
    Json(b): Json<ComplianceWaiveRequest>,
) -> ApiResult {
    // approved_by = authenticated caller (from request extensions), never a client
    // body field — the waiver's approval must name the real principal.
    if b.reason.trim().is_empty() {
        return Err(status_400("reason cannot be empty"));
    }
    if chrono::DateTime::parse_from_rfc3339(&b.expiry).is_err() {
        return Err(status_400(&format!("Invalid waiver expiry: {}", b.expiry)));
    }
    let pool = get_db().ok_or_else(status_503_no_db)?;
    // #2: scope on the finding's parent report site (join) before the waiver write;
    // out-of-scope or missing -> the same 404 "Finding not found".
    if is_scoped(&session) {
        let site: Option<String> = sqlx::query_scalar(
            "SELECT cr.site FROM compliance_findings cf \
             JOIN compliance_reports cr ON cf.report_id = cr.id WHERE cf.id = $1",
        )
        .bind(&id)
        .fetch_optional(pool)
        .await
        .map_err(db_error)?;
        if !site
            .map(|s| row_scope_permits(&session, &s, ""))
            .unwrap_or(false)
        {
            return Err((
                StatusCode::NOT_FOUND,
                Json(json!({"error": format!("Finding '{}' not found", id)})),
            ));
        }
    }
    use crate::repos::compliance_reporting::MutationOutcome;
    let mut tx = pool.begin().await.map_err(db_error)?;
    let outcome = crate::repos::compliance_reporting::create_waiver(
        &mut *tx,
        &id,
        &b.reason,
        &session.user_id,
        &b.expiry,
    )
    .await
    .map_err(db_error)?;
    let MutationOutcome::Updated(ref f) = outcome else {
        return Err((
            StatusCode::NOT_FOUND,
            Json(json!({"error": format!("Finding '{}' not found", id)})),
        ));
    };
    audit::record_audit_tx(
        &mut tx,
        &session,
        &audit::security_audit(
            "compliance-finding-waive",
            // No status guard + no prior-state read → don't claim a from_status.
            None,
            "waived",
            json!({ "finding_id": &id }),
        ),
    )
    .await
    .map_err(db_error)?;
    tx.commit().await.map_err(db_error)?;
    Ok(Json(json!({
        "source": "db",
        "waiver": {
            "finding_id": &id,
            "reason": &b.reason,
            "approved_by": &session.user_id,
            "expiry": &b.expiry,
            "created_at": chrono::Utc::now().to_rfc3339()
        },
        "finding": f
    })))
}

