async fn lb_status(
    AuthExtractor(session): AuthExtractor,
    Query(q): Query<LbSiteQuery>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    // #2: scoped-site read ("" = all sites for an unrestricted caller).
    let site_scoped = enforce_site_scope(&session, q.site.as_deref(), "")?;
    let site = site_scoped.as_str();
    let (vs_count, pool_count, up_members, down_members, offline_vs, draining_vs) = match get_db() {
        Some(pool) => crate::repos::load_balancer::get_lb_status(pool, site)
            .await
            .map_err(db_error)?,
        None => (0, 0, 0, 0, 0, 0),
    };
    Ok(Json(load_balancer::get_lb_status(
        site,
        vs_count,
        pool_count,
        up_members,
        down_members,
        offline_vs,
        draining_vs,
    )))
}
async fn lb_validate_vip(
    AuthExtractor(session): AuthExtractor,
    Json(b): Json<LbValidateVipRequest>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    // Pure validation first
    if b.vip.trim().is_empty() {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(json!({"error": "vip cannot be empty"})),
        ));
    }
    if b.site.trim().is_empty() {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(json!({"error": "site cannot be empty"})),
        ));
    }

    // #2: scoped principals may only probe VIP availability within their own
    // site; env-scoped principals are rejected (lb resources are site-only).
    // Without this, the conflict lookup leaks another site's VIP/VS data.
    guard_body_site_scope(&session, &b.site)?;

    let conflict = match get_db() {
        Some(pool) => crate::repos::load_balancer::find_vip_conflict(pool, &b.vip, &b.site)
            .await
            .map_err(db_error)?,
        None => None,
    };

    load_balancer::validate_vip(&b.vip, &b.site, conflict.as_ref())
        .map(Json)
        .map_err(|e| (StatusCode::BAD_REQUEST, Json(json!({"error": e}))))
}
async fn lb_contract() -> Json<Value> {
    Json(
        json!({"source":"static-seed","providerCallsEnabled":false,"liveExecutionEnabled":false,"endpoints":[{"method":"GET","path":"/api/network/loadbalancer/vs"},{"method":"POST","path":"/api/network/loadbalancer/vs"},{"method":"GET","path":"/api/network/loadbalancer/vs/{id}"},{"method":"POST","path":"/api/network/loadbalancer/vs/{id}/member"},{"method":"DELETE","path":"/api/network/loadbalancer/vs/{id}/member/{hostname}"},{"method":"POST","path":"/api/network/loadbalancer/vs/{id}/drain"},{"method":"POST","path":"/api/network/loadbalancer/vs/{id}/disable"},{"method":"POST","path":"/api/network/loadbalancer/vs/{id}/enable"},{"method":"GET","path":"/api/network/loadbalancer/status"},{"method":"POST","path":"/api/network/loadbalancer/validate-vip"}]}),
    )
}

