    #[tokio::test]
    async fn requests_validate_failure_does_not_mark_request_validated() {
        let id = format!("req-test-{}", Uuid::new_v4());
        let mut request = test_request(&id);
        request.site = "INVALID".into();

        request_store().lock().await.push(request);

        let Err((status, Json(body))) = requests_validate(
            Path(id.clone()),
            AuthExtractor(static_admin_operator_session()),
        )
        .await
        else {
            panic!("invalid request should fail validation");
        };

        assert_eq!(status, StatusCode::BAD_REQUEST);
        assert_eq!(body["error"], "Validation failed");
        assert_eq!(body["validation"]["passed"], false);

        let store = request_store().lock().await;
        let stored = store.iter().find(|request| request.id == id).unwrap();
        assert_eq!(stored.status, ryuki_engine::models::RequestStatus::Intake);
        assert!(stored.stages.iter().any(|stage| {
            stage.name == "validate" && stage.status == ryuki_engine::models::StageStatus::Failed
        }));
    }

    #[tokio::test]
    async fn requests_plan_requires_successful_validation() {
        let id = format!("req-test-{}", Uuid::new_v4());
        request_store().lock().await.push(test_request(&id));

        let Err((status, Json(body))) = requests_plan(
            Path(id.clone()),
            AuthExtractor(static_admin_operator_session()),
        )
        .await
        else {
            panic!("unvalidated request should not plan");
        };

        assert_eq!(status, StatusCode::BAD_REQUEST);
        assert!(body["error"]
            .as_str()
            .unwrap()
            .contains("successfully validated"));

        let store = request_store().lock().await;
        let stored = store.iter().find(|request| request.id == id).unwrap();
        assert_eq!(stored.status, ryuki_engine::models::RequestStatus::Intake);
    }

    #[tokio::test]
    async fn requests_validate_plan_approve_happy_path_still_works() {
        let id = format!("req-test-{}", Uuid::new_v4());
        request_store().lock().await.push(test_request(&id));

        let Json(validation) = requests_validate(
            Path(id.clone()),
            AuthExtractor(static_admin_operator_session()),
        )
        .await
        .expect("validation should pass");
        assert_eq!(validation["passed"], true);

        let Json(stages) = requests_plan(
            Path(id.clone()),
            AuthExtractor(static_admin_operator_session()),
        )
        .await
        .expect("planning should pass after validation");
        assert!(stages
            .as_array()
            .unwrap()
            .iter()
            .any(|stage| { stage["name"] == "plan" && stage["status"] == "Completed" }));

        let Json(approved) = requests_approve(
            Path(id.clone()),
            AuthExtractor(static_admin_operator_session()),
        )
        .await
        .expect("approval should pass after planning");
        assert_eq!(approved["status"], "Approved");

        let Json(locked) = requests_lock(
            Path(id.clone()),
            AuthExtractor(static_admin_operator_session()),
        )
        .await
        .expect("locking should pass after approval");
        assert_eq!(locked["status"], "Locked");

        let Json(executed) = requests_execute(
            Path(id.clone()),
            Query(ExecuteParams::default()),
            AuthExtractor(static_admin_operator_session()),
        )
        .await
        .expect("execution should pass after locking");
        assert_eq!(executed["status"], "Verifying");

        let Json(verification) = requests_verify(
            Path(id.clone()),
            AuthExtractor(static_admin_operator_session()),
        )
        .await
        .expect("verification should complete after execution");
        assert!(verification
            .as_array()
            .unwrap()
            .iter()
            .any(|item| { item["key"] == "verification-service-health" }));

        let store = request_store().lock().await;
        let stored = store.iter().find(|request| request.id == id).unwrap();
        assert_eq!(
            stored.status,
            ryuki_engine::models::RequestStatus::Completed
        );
        assert!(stored.stages.iter().any(|stage| {
            stage.name == "verify" && stage.status == ryuki_engine::models::StageStatus::Completed
        }));
    }

