    #[test]
    fn request_sort_is_allowlisted_and_injection_safe() {
        // Known columns map through; everything unknown (incl. an injection
        // attempt) falls back to created_at — never interpolated raw.
        assert_eq!(request_sort_column(Some("name")), "name");
        assert_eq!(request_sort_column(Some("updated_at")), "updated_at");
        assert_eq!(request_sort_column(None), "created_at");
        assert_eq!(
            request_sort_column(Some("created_at; DROP TABLE requests--")),
            "created_at"
        );
        // Direction is ASC only on an explicit case-insensitive "asc"; else DESC.
        assert_eq!(request_sort_direction(Some("asc")), "ASC");
        assert_eq!(request_sort_direction(Some("ASC")), "ASC");
        assert_eq!(request_sort_direction(Some("desc")), "DESC");
        assert_eq!(request_sort_direction(Some("garbage")), "DESC");
        assert_eq!(request_sort_direction(None), "DESC");
    }

    /// #9: the X-Total-Count header reports the FILTERED total (before
    /// limit/offset), not the page size — so a paginating client knows the page
    /// count. The body stays a bare array (backward-compatible).
    #[tokio::test]
    async fn requests_list_total_count_header_reflects_filtered_total() {
        let site = "RLTOTAL-z9"; // unique site so other tests' rows don't match
        for i in 0..3 {
            let mut r = test_request(&format!("rl-total-{i}"));
            r.site = site.into();
            request_store().lock().await.push(r);
        }
        let (headers, Json(body)) = requests_list(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(RequestListParams {
                limit: Some(2),
                offset: Some(0),
                site: Some(site.into()),
                ..Default::default()
            }),
        )
        .await
        .expect("list");
        assert_eq!(
            body.as_array().unwrap().len(),
            2,
            "the page body is capped at limit=2"
        );
        let total = headers
            .get("x-total-count")
            .expect("X-Total-Count header present")
            .to_str()
            .unwrap();
        assert_eq!(
            total, "3",
            "X-Total-Count must be the filtered total (3), not the page size (2)"
        );
    }

    #[tokio::test]
    async fn requests_list_filters_in_memory_by_status_site_and_q() {
        let mut a = test_request("rl-filter-a");
        a.site = "DEFRA".into();
        a.requester = "alice-deploy".into();
        let mut b = test_request("rl-filter-b");
        b.site = "GBLON".into();
        b.requester = "bob-deploy".into();
        {
            let mut store = request_store().lock().await;
            store.push(a);
            store.push(b);
        }

        let ids = |body: &Value| -> Vec<String> {
            body.as_array()
                .unwrap()
                .iter()
                .map(|i| i["request_id"].as_str().unwrap_or_default().to_string())
                .collect()
        };

        // Filter by site → only the DEFRA row.
        let (_, Json(by_site)) = requests_list(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(RequestListParams {
                site: Some("DEFRA".into()),
                ..Default::default()
            }),
        )
        .await
        .expect("an unrestricted session lists requests");
        let site_ids = ids(&by_site);
        assert!(site_ids.contains(&"rl-filter-a".to_string()));
        assert!(!site_ids.contains(&"rl-filter-b".to_string()));

        // Case-insensitive substring on the (requester) name.
        let (_, Json(by_q)) = requests_list(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(RequestListParams {
                q: Some("BOB".into()),
                ..Default::default()
            }),
        )
        .await
        .expect("an unrestricted session lists requests");
        let q_ids = ids(&by_q);
        assert!(q_ids.contains(&"rl-filter-b".to_string()));
        assert!(!q_ids.contains(&"rl-filter-a".to_string()));

        // A blank filter is ignored (both rows listed).
        let (_, Json(blank)) = requests_list(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(RequestListParams {
                site: Some("   ".into()),
                ..Default::default()
            }),
        )
        .await
        .expect("an unrestricted session lists requests");
        let blank_ids = ids(&blank);
        assert!(blank_ids.contains(&"rl-filter-a".to_string()));
        assert!(blank_ids.contains(&"rl-filter-b".to_string()));
    }

    // ─── API token & session administration ───

    #[test]
    fn test_generate_api_token_format() {
        let token = generate_api_token();
        // ryk_ prefix + 43 base64url-no-pad chars (32 bytes) = 47 total.
        assert!(token.starts_with(crate::API_TOKEN_PREFIX));
        assert_eq!(token.len(), 47);
        let suffix = token.strip_prefix(crate::API_TOKEN_PREFIX).unwrap();
        assert_eq!(suffix.len(), 43);
        assert!(suffix
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_'));
    }

    #[test]
    fn test_generate_api_token_is_unique_per_call() {
        // CSPRNG: two mints are (astronomically certainly) distinct, and their
        // hashes differ — so neither the token nor its hash is ever a literal.
        let a = generate_api_token();
        let b = generate_api_token();
        assert_ne!(a, b);
        assert_ne!(crate::sha256_hex(&a), crate::sha256_hex(&b));
    }

