    #[test]
    fn retain_site_scoped_filters_list_all_rows() {
        #[derive(Clone)]
        struct Row {
            site: String,
        }
        let rows = || {
            vec![
                Row {
                    site: "GBLON".into(),
                },
                Row {
                    site: "DEFRA".into(),
                },
            ]
        };
        // Unrestricted → all rows.
        assert_eq!(
            retain_site_scoped(&AuthSession::static_dry_run(), rows(), |r| &r.site).len(),
            2
        );
        // Site-scoped → only the principal's own site.
        let kept = retain_site_scoped(&scoped_session(&["GBLON"], &[]), rows(), |r| &r.site);
        assert_eq!(kept.len(), 1);
        assert_eq!(kept[0].site, "GBLON");
        // Environment-scoped → NONE (these list-all resources are site-only, so an
        // environment scope cannot be honored — fail closed to empty, never leak).
        assert!(
            retain_site_scoped(&scoped_session(&[], &["production"]), rows(), |r| &r.site)
                .is_empty()
        );
    }

    // ── swarm #14: auth bodies reject unknown fields (no silent field-drop) ──

    #[test]
    fn auth_request_structs_reject_unknown_fields() {
        // Valid bodies still deserialize.
        assert!(
            serde_json::from_str::<LocalLoginRequest>(r#"{"username":"u","password":"p"}"#).is_ok()
        );
        assert!(serde_json::from_str::<CreateTokenRequest>(
            r#"{"name":"n","owner_principal":"o"}"#
        )
        .is_ok());
        // An extra/typo'd field is a HARD error, never silently dropped.
        assert!(
            serde_json::from_str::<LocalLoginRequest>(
                r#"{"username":"u","password":"p","extra":"x"}"#
            )
            .is_err(),
            "unknown field on login must be rejected"
        );
        assert!(
            serde_json::from_str::<CreateTokenRequest>(
                r#"{"name":"n","owner_principal":"o","evil":1}"#
            )
            .is_err(),
            "unknown field on token-create must be rejected"
        );
    }

