    /// #45: usage metering aggregates requests per site, broken down by status,
    /// over the window.
    #[tokio::test]
    async fn test_metering_usage_aggregates_by_site() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let site = "TESTMETER-9q";
        sqlx::query("DELETE FROM requests WHERE site = $1")
            .bind(site)
            .execute(pool)
            .await
            .ok();
        for status in ["intake", "intake", "completed"] {
            sqlx::query(
                "INSERT INTO requests (id, request_type, status, stage, site, environment, name) \
                 VALUES ($1, 'server-deployment', $2, 'intake', $3, 'production', 'metering-test')",
            )
            .bind(uuid::Uuid::new_v4())
            .bind(status)
            .bind(site)
            .execute(pool)
            .await
            .expect("insert request");
        }

        let Json(out) = metering_usage(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(MeteringQuery {
                since: None,
                until: None,
                site: Some(site.to_string()),
            }),
        )
        .await
        .expect("metering");
        let sites = out["sites"].as_array().unwrap();
        assert_eq!(sites.len(), 1, "one site");
        assert_eq!(sites[0]["request_count"], 3, "three requests");
        assert_eq!(sites[0]["by_status"]["intake"], 2);
        assert_eq!(sites[0]["by_status"]["completed"], 1);

        sqlx::query("DELETE FROM requests WHERE site = $1")
            .bind(site)
            .execute(pool)
            .await
            .ok();
    }

    /// #46: chargeback applies a per-request-type rate to the per-site usage —
    /// 4 requests at $2.50 each allocates $10.00 to the site.
    #[tokio::test]
    async fn test_chargeback_allocates_cost_by_rate() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let site = "TESTCHARGE-3k";
        // A VALID request_type (mig 109 CHECK); the chargeback math is independent
        // of which type. cost_rates has no seed data + the DB-test serial lock, so
        // setting/clearing this type's rate cannot collide.
        let rtype = "server-deployment";
        sqlx::query("DELETE FROM requests WHERE site = $1")
            .bind(site)
            .execute(pool)
            .await
            .ok();
        sqlx::query("DELETE FROM cost_rates WHERE request_type = $1")
            .bind(rtype)
            .execute(pool)
            .await
            .ok();

        let sess = || AuthExtractor(AuthSession::static_dry_run());
        let _ = chargeback_rate_set(
            sess(),
            Json(CostRateRequest {
                request_type: rtype.to_string(),
                unit_cost: 2.5,
                currency: None,
            }),
        )
        .await
        .expect("set rate");
        for _ in 0..4 {
            sqlx::query(
                "INSERT INTO requests (id, request_type, status, stage, site, environment, name) \
                 VALUES ($1, $2, 'intake', 'intake', $3, 'production', 'charge-test')",
            )
            .bind(uuid::Uuid::new_v4())
            .bind(rtype)
            .bind(site)
            .execute(pool)
            .await
            .expect("insert request");
        }

        let Json(out) = chargeback_report(
            sess(),
            Query(MeteringQuery {
                since: None,
                until: None,
                site: Some(site.to_string()),
            }),
        )
        .await
        .expect("chargeback");
        let sites = out["sites"].as_array().unwrap();
        assert_eq!(sites.len(), 1, "one site");
        assert!(
            (sites[0]["total_cost"].as_f64().unwrap() - 10.0).abs() < 1e-9,
            "4 x $2.50 = $10.00"
        );
        assert_eq!(out["currency"], "USD");

        sqlx::query("DELETE FROM requests WHERE site = $1")
            .bind(site)
            .execute(pool)
            .await
            .ok();
        sqlx::query("DELETE FROM cost_rates WHERE request_type = $1")
            .bind(rtype)
            .execute(pool)
            .await
            .ok();
    }

    /// B4 (a)+(c): logout deletes ONLY the caller's own session and writes a
