    /// #2 RBAC: metric_budgets is dual-axis & nullable (NULL = platform-wide). A
    /// scoped principal cannot delete a DEFRA-site budget (404, unmutated) nor a
    /// platform-wide one (404). Uses an execute-tier session; negatives only, so
    /// the guard fires before any DELETE.
    #[tokio::test]
    async fn metrics_budget_is_site_scoped() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set");
            return;
        };
        // execute-tier session (metrics_budget_delete requires "execute"), scoped to GBLON.
        let mut gblon = AuthSession::static_dry_run();
        gblon
            .roles
            .push(ryuki_engine::auth::APP_ROLE_VMWARE_OPERATOR.to_string());
        gblon.site_scope = vec!["GBLON".into()];

        // out-of-scope (DEFRA-site) budget -> 404, and it must NOT be deleted.
        if let Some(id) = sqlx::query_scalar::<_, String>(
            "SELECT id FROM metric_budgets WHERE site = 'DEFRA' LIMIT 1",
        )
        .fetch_optional(pool)
        .await
        .unwrap_or(None)
        {
            let del = metrics_budget_delete(AuthExtractor(gblon.clone()), Path(id.clone())).await;
            assert!(
                matches!(del, Err((StatusCode::NOT_FOUND, _))),
                "out-of-scope metrics_budget_delete must 404: {del:?}"
            );
            let still: Option<String> =
                sqlx::query_scalar("SELECT id FROM metric_budgets WHERE id = $1")
                    .bind(&id)
                    .fetch_optional(pool)
                    .await
                    .expect("re-read budget");
            assert!(
                still.is_some(),
                "out-of-scope delete must NOT have removed the budget"
            );
        }

        // a platform-wide (site IS NULL) budget -> 404 for a scoped principal.
        if let Some(id) = sqlx::query_scalar::<_, String>(
            "SELECT id FROM metric_budgets WHERE site IS NULL LIMIT 1",
        )
        .fetch_optional(pool)
        .await
        .unwrap_or(None)
        {
            let del = metrics_budget_delete(AuthExtractor(gblon), Path(id)).await;
            assert!(
                matches!(del, Err((StatusCode::NOT_FOUND, _))),
                "scoped delete of a platform-wide budget must 404: {del:?}"
            );
        }
    }

    /// Read the raw persisted row through the global pool (so it observes what
    /// the handlers wrote), bypassing the in-memory store.
    async fn read_global_row(pool: &PgPool, id: Uuid) -> DbRequestRow {
        sqlx::query_as(&format!(
            "SELECT {REQUEST_COLUMNS} FROM requests WHERE id = $1"
        ))
        .bind(id)
        .fetch_one(pool)
        .await
        .expect("read global row")
    }

    fn create_body(request_type: &str) -> CreateRequest {
        CreateRequest {
            request_type: request_type.into(),
            site: "DEFRA".into(),
            environment: "production".into(),
            name: format!("p2-{request_type}"),
            cpu: 4,
            memory_gb: 8,
            justification: "p2 durable-state test".into(),
            fields: std::collections::BTreeMap::new(),
        }
    }

    /// #9 (DB path): requests_list's X-Total-Count header comes from the COUNT(*)
    /// query — this validates that SQL runs against Postgres and reflects the
    /// filtered total independent of the page limit. Uses a before/after DELTA on
    /// a unique requester (created_by = the verified session principal) so it is
    /// robust to leftover rows + FK constraints (requests has audit/job children,
    /// so a plain DELETE cleanup is unreliable).
    #[tokio::test]
    async fn requests_list_db_total_count_header() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(_pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let user = "rl-dbtotal-7q3";
        let list = |reader: AuthSession| async move {
            requests_list(
                AuthExtractor(reader),
                Query(RequestListParams {
                    limit: Some(1),
                    offset: Some(0),
                    created_by: Some(user.into()),
                    ..Default::default()
                }),
            )
            .await
            .expect("list")
        };
        let total_of = |headers: &HeaderMap| -> i64 {
            headers
                .get("x-total-count")
                .expect("X-Total-Count header present")
                .to_str()
                .unwrap()
                .parse()
                .expect("X-Total-Count is a number")
        };

        let (before_headers, _) = list(admin_session("rl-dbtotal-reader")).await;
        let before = total_of(&before_headers);

        let session = admin_session(user);
        for _ in 0..2 {
            let _created = requests_create(
                AuthExtractor(session.clone()),
                Json(create_body("server-deployment")),
            )
            .await
            .expect("create");
        }

        let (after_headers, Json(after_body)) = list(admin_session("rl-dbtotal-reader")).await;
        assert_eq!(
            after_body.as_array().unwrap().len(),
            1,
            "the page body is capped at limit=1 regardless of the total"
        );
        assert_eq!(
            total_of(&after_headers),
            before + 2,
            "X-Total-Count (from COUNT(*)) must grow by exactly the 2 created rows"
        );
    }

    /// #10: enforce_site_operational blocks a degraded/unreachable site (the
    /// live-execution gate) and allows healthy/unknown sites — read from the
    /// persisted site_status (mig 025 seed). Non-mutating.
    #[tokio::test]
    async fn enforce_site_operational_blocks_degraded_sites() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        // GBLON seeded 'degraded', NLAMS seeded 'unreachable' → blocked (503).
        let gblon = super::enforce_site_operational(pool, "GBLON").await;
        assert!(
            matches!(gblon, Err((StatusCode::SERVICE_UNAVAILABLE, _))),
            "degraded site GBLON must be blocked: {gblon:?}"
        );
        let nlams = super::enforce_site_operational(pool, "NLAMS").await;
        assert!(
            matches!(nlams, Err((StatusCode::SERVICE_UNAVAILABLE, _))),
            "unreachable site NLAMS must be blocked: {nlams:?}"
        );
        // DEFRA seeded 'healthy' → allowed; an unknown site (no row) → allowed.
        super::enforce_site_operational(pool, "DEFRA")
            .await
            .expect("healthy site DEFRA must be allowed");
        super::enforce_site_operational(pool, "ZZ-NONEXISTENT")
            .await
            .expect("a site with no status row must be allowed");
    }

    /// #15: a scope-preference change (preferred_site/environment) is a
    /// security-relevant mutation and must leave a durable audit trail. Assert
    /// `user_preferences_put` writes a `user.preferences.update` audit_log row
    /// for the acting principal (before/after delta — audit_log is append-only).
    #[tokio::test]
    async fn user_preferences_put_writes_audit_row() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let actor = "prefs-audit-test-user";
        let count = |p: &'static PgPool| async move {
            sqlx::query_scalar::<_, i64>(
                "SELECT COUNT(*) FROM audit_log \
                 WHERE action = 'user.preferences.update' AND actor_principal = $1",
            )
            .bind(actor)
            .fetch_one(p)
            .await
            .expect("count audit rows")
        };
        let before = count(pool).await;

        let mut session = AuthSession::static_dry_run();
        session.user_id = actor.into();
        let resp = user_preferences_put(
            AuthExtractor(session),
            Json(UserPreferencesRequest {
                preferred_site: Some("GBLON".into()),
                preferred_environment: Some("prod".into()),
            }),
        )
        .await
        .expect("preferences upsert must succeed");
        assert_eq!(resp.0["durable"], json!(true));

        let after = count(pool).await;
        assert_eq!(
            after,
            before + 1,
            "a preferences update must append exactly one audit row"
        );
    }

