    /// #11: the domain-event repo + GET /api/events feed — insert events, filter
    /// by aggregate_id / event_type, and apply site scope (platform-wide NULL-site
    /// events stay visible to a scoped principal; another site's events do not).
    #[tokio::test]
    async fn domain_events_insert_list_filter_and_scope() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let agg = format!("evt-test-{}", Uuid::new_v4());
        crate::repos::domain_events::insert(
            pool,
            crate::repos::domain_events::NewEvent {
                event_type: "request.approve",
                aggregate_type: "request",
                aggregate_id: &agg,
                site: Some("GBLON"),
                environment: Some("prod"),
                actor: "evt-test-actor",
                payload: json!({ "to_status": "approved" }),
            },
        )
        .await
        .expect("insert GBLON event");
        crate::repos::domain_events::insert(
            pool,
            crate::repos::domain_events::NewEvent {
                event_type: "request.verify",
                aggregate_type: "request",
                aggregate_id: &agg,
                site: None,
                environment: None,
                actor: "evt-test-actor",
                payload: json!({}),
            },
        )
        .await
        .expect("insert platform-wide event");

        // Unrestricted admin: both events for the aggregate.
        let resp = events_list(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(EventsQuery {
                event_type: None,
                aggregate_id: Some(agg.clone()),
                limit: Some(100),
            }),
        )
        .await
        .expect("list must succeed");
        assert_eq!(resp.0["durable"], json!(true));
        assert_eq!(
            resp.0["events"].as_array().expect("events").len(),
            2,
            "both events for the aggregate must return"
        );

        // event_type filter narrows to one.
        let approve_only = events_list(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(EventsQuery {
                event_type: Some("request.approve".into()),
                aggregate_id: Some(agg.clone()),
                limit: Some(100),
            }),
        )
        .await
        .expect("filtered list");
        assert_eq!(
            approve_only.0["events"].as_array().unwrap().len(),
            1,
            "event_type filter must narrow to one"
        );

        // A DEFRA-scoped principal sees the platform-wide (NULL-site) event but
        // NOT the GBLON event.
        let mut defra = AuthSession::static_dry_run();
        defra.site_scope = vec!["DEFRA".into()];
        let scoped = events_list(
            AuthExtractor(defra),
            Query(EventsQuery {
                event_type: None,
                aggregate_id: Some(agg.clone()),
                limit: Some(100),
            }),
        )
        .await
        .expect("scoped list");
        let scoped_events = scoped.0["events"].as_array().unwrap();
        assert!(
            scoped_events.iter().all(|e| e["site"] != json!("GBLON")),
            "a DEFRA-scoped principal must not see GBLON events: {scoped_events:?}"
        );
        assert!(
            scoped_events.iter().any(|e| e["site"].is_null()),
            "platform-wide (NULL-site) events must stay visible to a scoped principal"
        );

        // #11: the stream is append-only (migration 111) — a DELETE must be
        // rejected by the guard trigger, never silently succeed. (No cleanup:
        // events use a unique aggregate_id per run, so they don't accumulate
        // into the assertions.)
        let delete_attempt = sqlx::query("DELETE FROM domain_events WHERE aggregate_id = $1")
            .bind(&agg)
            .execute(pool)
            .await;
        assert!(
            delete_attempt.is_err(),
            "domain_events must be append-only: a DELETE must be rejected"
        );
    }

    /// #11 slice 2a: GET /api/events/alerts returns only the alert-worthy events
    /// (requests reaching a negative terminal state) with the right severity, and
    /// excludes normal-flow events.
    #[tokio::test]
    async fn events_alerts_returns_only_alert_worthy_with_severity() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let agg = format!("evt-alert-{}", Uuid::new_v4());
        for (event_type, to_status) in [
            ("request.reject", "rejected"),
            ("request.execute", "failed"),
            ("request.verify", "completed"),
        ] {
            crate::repos::domain_events::insert(
                pool,
                crate::repos::domain_events::NewEvent {
                    event_type,
                    aggregate_type: "request",
                    aggregate_id: &agg,
                    site: None,
                    environment: None,
                    actor: "evt-alert-actor",
                    payload: json!({ "to_status": to_status }),
                },
            )
            .await
            .expect("insert event");
        }

        let resp = events_alerts(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(EventsQuery {
                event_type: None,
                aggregate_id: Some(agg.clone()),
                limit: Some(100),
            }),
        )
        .await
        .expect("alerts list must succeed");
        let alerts = resp.0["alerts"].as_array().expect("alerts array");
        assert_eq!(
            alerts.len(),
            2,
            "only the rejected + failed events are alerts (completed is not): {alerts:?}"
        );
        let by_status: std::collections::HashMap<String, String> = alerts
            .iter()
            .map(|a| {
                (
                    a["payload"]["to_status"].as_str().unwrap().to_string(),
                    a["severity"].as_str().unwrap().to_string(),
                )
            })
            .collect();
        assert_eq!(
            by_status.get("rejected").map(String::as_str),
            Some("warning")
        );
        assert_eq!(
            by_status.get("failed").map(String::as_str),
            Some("critical")
        );
        assert!(
            !by_status.contains_key("completed"),
            "a completed request must not be an alert"
        );
    }

    /// #11 slice 2b: the SLO-breach scan emits slo.breach on the breach
    /// transition, dedups (no re-emit while still breaching), surfaces as a
    /// critical alert, and emits slo.recovered when the SLO recovers.
    #[tokio::test]
    async fn slo_breach_scan_emits_on_transition_and_dedups() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let suffix = Uuid::new_v4().simple().to_string();
        let good_key = format!("slo.scan.good.{suffix}");
        let total_key = format!("slo.scan.total.{suffix}");
        let created = slo_create(
            AuthExtractor(AuthSession::static_dry_run()),
            Json(SloCreateRequest {
                name: format!("scan-test-{suffix}"),
                target: 0.99,
                window_days: Some(30),
                good_metric_key: good_key.clone(),
                total_metric_key: total_key.clone(),
                site: None,
                environment: None,
            }),
        )
        .await
        .expect("create slo");
        let slo_id = created.0["id"].as_str().unwrap().to_string();

        let sample =
            "INSERT INTO metric_samples (id, metric_key, site, environment, value, observed_at) \
                      VALUES ($1, $2, NULL, NULL, $3, NOW())";
        // Breach: good=1, total=100 → attainment 0.01 < 0.99.
        sqlx::query(sample)
            .bind(Uuid::new_v4().to_string())
            .bind(&good_key)
            .bind(1.0_f64)
            .execute(pool)
            .await
            .expect("seed good");
        sqlx::query(sample)
            .bind(Uuid::new_v4().to_string())
            .bind(&total_key)
            .bind(100.0_f64)
            .execute(pool)
            .await
            .expect("seed total");

        assert_eq!(
            slo_breach_scan_once(pool).await.expect("scan 1"),
            1,
            "first breach must emit one transition event"
        );
        assert_eq!(
            slo_breach_scan_once(pool).await.expect("scan 2"),
            0,
            "an already-breaching SLO must not re-emit (dedup)"
        );

        let alerts = events_alerts(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(EventsQuery {
                event_type: None,
                aggregate_id: Some(slo_id.clone()),
                limit: Some(50),
            }),
        )
        .await
        .expect("alerts list");
        let arr = alerts.0["alerts"].as_array().unwrap();
        assert!(
            arr.iter()
                .any(|a| a["event_type"] == json!("slo.breach")
                    && a["severity"] == json!("critical")),
            "the SLO breach must surface as a critical alert: {arr:?}"
        );

        // #11 slice 2f: the breach also pushed exactly one MonitoringOperator
        // portal notification (the body carries this SLO's id).
        let notif_n: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM portal_notifications \
             WHERE event = 'slo.breach' AND recipient_id = 'MonitoringOperator' AND body LIKE $1",
        )
        .bind(format!("%{slo_id}%"))
        .fetch_one(pool)
        .await
        .expect("count alert notifications");
        assert_eq!(
            notif_n, 1,
            "an SLO breach must push exactly one MonitoringOperator notification"
        );

        // Recover: add good=99 → good=100, total=100 → attainment 1.0 ≥ 0.99.
        sqlx::query(sample)
            .bind(Uuid::new_v4().to_string())
            .bind(&good_key)
            .bind(99.0_f64)
            .execute(pool)
            .await
            .expect("seed recovery");
        assert_eq!(
            slo_breach_scan_once(pool).await.expect("scan 3"),
            1,
            "recovery must emit one transition event"
        );
        let breaching: bool =
            sqlx::query_scalar("SELECT breaching FROM slo_definitions WHERE id = $1")
                .bind(&slo_id)
                .fetch_one(pool)
                .await
                .expect("read breaching flag");
        assert!(!breaching, "SLO must no longer be breaching after recovery");

        // #11 slice 2g: recovery pushed a Success "all-clear" notification too.
        let recovered_n: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM portal_notifications \
             WHERE event = 'slo.recovered' AND severity = 'Success' AND body LIKE $1",
        )
        .bind(format!("%{slo_id}%"))
        .fetch_one(pool)
        .await
        .expect("count recovery notifications");
        assert_eq!(
            recovered_n, 1,
            "recovery must push exactly one Success notification"
        );

        // Cleanup (domain_events is append-only and intentionally retained).
        sqlx::query("DELETE FROM portal_notifications WHERE body LIKE $1")
            .bind(format!("%{slo_id}%"))
            .execute(pool)
            .await
            .ok();
        sqlx::query("DELETE FROM slo_definitions WHERE id = $1")
            .bind(&slo_id)
            .execute(pool)
            .await
            .ok();
        sqlx::query("DELETE FROM metric_samples WHERE metric_key = $1 OR metric_key = $2")
            .bind(&good_key)
            .bind(&total_key)
            .execute(pool)
            .await
            .ok();
    }

    /// #11 slice 2c: the budget-breach scan emits budget.breach on the breach
    /// transition, dedups, surfaces as a WARNING alert, and emits budget.recovered
    /// when the metric drops back under the threshold.
    #[tokio::test]
    async fn budget_breach_scan_emits_on_transition_and_dedups() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let suffix = Uuid::new_v4().simple().to_string();
        let key = format!("cost.scan.{suffix}");
        let created = metrics_budget_create(
            AuthExtractor(AuthSession::static_dry_run()),
            Json(MetricBudgetCreateRequest {
                metric_key: key.clone(),
                site: None,
                environment: None,
                threshold: 10.0,
                comparison: Some("above".into()),
            }),
        )
        .await
        .expect("create budget");
        let budget_id = created.0["id"].as_str().unwrap().to_string();

        let sample =
            "INSERT INTO metric_samples (id, metric_key, site, environment, value, observed_at) \
                      VALUES ($1, $2, NULL, NULL, $3, $4)";
        let now = chrono::Utc::now();
        // Breach: latest value 100 > threshold 10.
        sqlx::query(sample)
            .bind(Uuid::new_v4().to_string())
            .bind(&key)
            .bind(100.0_f64)
            .bind(now - chrono::Duration::minutes(5))
            .execute(pool)
            .await
            .expect("seed breach sample");

        assert_eq!(
            budget_breach_scan_once(pool).await.expect("scan 1"),
            1,
            "first breach must emit one transition event"
        );
        assert_eq!(
            budget_breach_scan_once(pool).await.expect("scan 2"),
            0,
            "an already-breaching budget must not re-emit (dedup)"
        );

        let alerts = events_alerts(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(EventsQuery {
                event_type: None,
                aggregate_id: Some(budget_id.clone()),
                limit: Some(50),
            }),
        )
        .await
        .expect("alerts list");
        let arr = alerts.0["alerts"].as_array().unwrap();
        assert!(
            arr.iter()
                .any(|a| a["event_type"] == json!("budget.breach")
                    && a["severity"] == json!("warning")),
            "the budget breach must surface as a warning alert: {arr:?}"
        );

        // Recover: later low samples → latest 1 ≤ 10 and a downward trend.
        for off in [3i64, 2, 1] {
            sqlx::query(sample)
                .bind(Uuid::new_v4().to_string())
                .bind(&key)
                .bind(1.0_f64)
                .bind(now - chrono::Duration::minutes(off))
                .execute(pool)
                .await
                .expect("seed recovery sample");
        }
        assert_eq!(
            budget_breach_scan_once(pool).await.expect("scan 3"),
            1,
            "recovery must emit one transition event"
        );
        let breaching: bool =
            sqlx::query_scalar("SELECT breaching FROM metric_budgets WHERE id = $1")
                .bind(&budget_id)
                .fetch_one(pool)
                .await
                .expect("read breaching flag");
        assert!(
            !breaching,
            "budget must no longer be breaching after recovery"
        );

        sqlx::query("DELETE FROM metric_budgets WHERE id = $1")
            .bind(&budget_id)
            .execute(pool)
            .await
            .ok();
        sqlx::query("DELETE FROM metric_samples WHERE metric_key = $1")
            .bind(&key)
            .execute(pool)
            .await
            .ok();
    }

    /// #11 slice 2d: the agent-offline scan emits agent.offline when an approved
    /// agent goes stale, dedups, surfaces as a warning alert, and emits
    /// agent.online when it checks back in. Asserts on THIS agent's events (the
    /// scan covers all approved agents, so the global count is not deterministic).
    #[tokio::test]
    async fn agent_offline_scan_emits_on_transition_and_dedups() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let suffix = Uuid::new_v4().simple().to_string();
        let agent_id = format!("agent-offline-test-{suffix}");
        sqlx::query(
            "INSERT INTO agents (agent_id, platform, public_key, token_hash, status, last_seen_at) \
             VALUES ($1, 'vmware', 'pk', $2, 'approved', NOW() - INTERVAL '10 minutes')",
        )
        .bind(&agent_id)
        .bind(format!("hash-{suffix}"))
        .execute(pool)
        .await
        .expect("seed approved agent");

        let count_sql =
            "SELECT COUNT(*) FROM domain_events WHERE aggregate_id = $1 AND event_type = $2";

        // Scan 1: my agent (last seen 10 min ago, threshold 180s) → offline.
        crate::agents::agent_offline_scan_once(pool, 180)
            .await
            .expect("scan 1");
        let offline_n: i64 = sqlx::query_scalar(count_sql)
            .bind(&agent_id)
            .bind("agent.offline")
            .fetch_one(pool)
            .await
            .expect("count offline");
        assert_eq!(offline_n, 1, "offline must be emitted once");
        let flagged: bool =
            sqlx::query_scalar("SELECT offline_alerted FROM agents WHERE agent_id = $1")
                .bind(&agent_id)
                .fetch_one(pool)
                .await
                .expect("flag");
        assert!(flagged, "agent must be flagged offline");

        // Scan 2: dedup — no second offline event for this agent.
        crate::agents::agent_offline_scan_once(pool, 180)
            .await
            .expect("scan 2");
        let offline_n2: i64 = sqlx::query_scalar(count_sql)
            .bind(&agent_id)
            .bind("agent.offline")
            .fetch_one(pool)
            .await
            .expect("count offline 2");
        assert_eq!(offline_n2, 1, "an already-offline agent must not re-emit");

        // Surfaced as a warning alert.
        let alerts = events_alerts(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(EventsQuery {
                event_type: None,
                aggregate_id: Some(agent_id.clone()),
                limit: Some(50),
            }),
        )
        .await
        .expect("alerts");
        let arr = alerts.0["alerts"].as_array().unwrap();
        assert!(
            arr.iter()
                .any(|a| a["event_type"] == json!("agent.offline")
                    && a["severity"] == json!("warning")),
            "the agent offline must surface as a warning alert: {arr:?}"
        );

        // Recover: agent checks back in.
        sqlx::query("UPDATE agents SET last_seen_at = NOW() WHERE agent_id = $1")
            .bind(&agent_id)
            .execute(pool)
            .await
            .expect("heartbeat");
        crate::agents::agent_offline_scan_once(pool, 180)
            .await
            .expect("scan 3");
        let online_n: i64 = sqlx::query_scalar(count_sql)
            .bind(&agent_id)
            .bind("agent.online")
            .fetch_one(pool)
            .await
            .expect("count online");
        assert_eq!(online_n, 1, "online must be emitted once on recovery");
        let flagged2: bool =
            sqlx::query_scalar("SELECT offline_alerted FROM agents WHERE agent_id = $1")
                .bind(&agent_id)
                .fetch_one(pool)
                .await
                .expect("flag 2");
        assert!(!flagged2, "agent must no longer be flagged offline");

        sqlx::query("DELETE FROM agents WHERE agent_id = $1")
            .bind(&agent_id)
            .execute(pool)
            .await
            .ok();
    }

    /// #11 slice 2e: acknowledging an alert marks it (and only it) acknowledged
    /// in the feed, records who, and 404s an unknown event id.
    #[tokio::test]
    async fn events_alert_ack_marks_alert_acknowledged() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let agg = format!("ack-test-{}", Uuid::new_v4());
        let event_id = crate::repos::domain_events::insert(
            pool,
            crate::repos::domain_events::NewEvent {
                event_type: "request.reject",
                aggregate_type: "request",
                aggregate_id: &agg,
                site: None,
                environment: None,
                actor: "creator",
                payload: json!({ "to_status": "rejected" }),
            },
        )
        .await
        .expect("insert alert event");

        let q = |aid: String| EventsQuery {
            event_type: None,
            aggregate_id: Some(aid),
            limit: Some(50),
        };

        // Before ack: present, not acknowledged.
        let before = events_alerts(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(q(agg.clone())),
        )
        .await
        .expect("alerts before");
        let a = before.0["alerts"]
            .as_array()
            .unwrap()
            .iter()
            .find(|a| a["id"] == json!(event_id))
            .expect("alert present before ack")
            .clone();
        assert_eq!(a["acknowledged"], json!(false));

        // Acknowledge as a specific operator.
        let mut acker = AuthSession::static_dry_run();
        acker.user_id = "ops-ack-user".into();
        let resp = events_alert_ack(
            AuthExtractor(acker),
            Path(event_id),
            Json(AlertAckBody {
                note: Some("looking into it".into()),
            }),
        )
        .await
        .expect("ack must succeed");
        assert_eq!(resp.0["acknowledged"], json!(true));

        // After ack: acknowledged=true, attributed to the operator.
        let after = events_alerts(
            AuthExtractor(AuthSession::static_dry_run()),
            Query(q(agg.clone())),
        )
        .await
        .expect("alerts after");
        let a2 = after.0["alerts"]
            .as_array()
            .unwrap()
            .iter()
            .find(|a| a["id"] == json!(event_id))
            .expect("alert present after ack")
            .clone();
        assert_eq!(a2["acknowledged"], json!(true));
        assert_eq!(a2["acknowledged_by"], json!("ops-ack-user"));

        // An unknown event id is a 404.
        let missing = events_alert_ack(
            AuthExtractor(AuthSession::static_dry_run()),
            Path(-999_i64),
            Json(AlertAckBody::default()),
        )
        .await;
        assert!(
            matches!(missing, Err((StatusCode::NOT_FOUND, _))),
            "an unknown event id must 404: {missing:?}"
        );

        // alert_acks is mutable; clean it (domain_events is append-only, kept).
        sqlx::query("DELETE FROM alert_acks WHERE event_id = $1")
            .bind(event_id)
            .execute(pool)
            .await
            .ok();
    }

    /// #2 RBAC: events_alert_ack matches the alert feed's visibility model
    /// (domain_events::list_alerts) — a scoped principal may ack an alert tagged to
    /// an in-scope site OR platform-wide (NULL site), but acking an alert tagged to
    /// another site 404s like a missing event (no cross-site oracle).
    #[tokio::test]
    async fn events_alert_ack_is_scope_filtered() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let defra_tag = format!("ack-defra-{}", Uuid::new_v4());
        let global_tag = format!("ack-global-{}", Uuid::new_v4());
        let defra_id = crate::repos::domain_events::insert(
            pool,
            crate::repos::domain_events::NewEvent {
                event_type: "request.reject",
                aggregate_type: "request",
                aggregate_id: &defra_tag,
                site: Some("DEFRA"),
                environment: None,
                actor: "creator",
                payload: json!({ "to_status": "rejected" }),
            },
        )
        .await
        .expect("insert DEFRA alert");
        let global_id = crate::repos::domain_events::insert(
            pool,
            crate::repos::domain_events::NewEvent {
                event_type: "request.reject",
                aggregate_type: "request",
                aggregate_id: &global_tag,
                site: None,
                environment: None,
                actor: "creator",
                payload: json!({ "to_status": "rejected" }),
            },
        )
        .await
        .expect("insert platform-wide alert");

        let scoped = || {
            let mut s = AuthSession::static_dry_run();
            s.site_scope = vec!["GBLON".into()];
            s
        };

        // Cross-site (DEFRA) alert → 404 for a GBLON-scoped principal.
        let r = events_alert_ack(
            AuthExtractor(scoped()),
            Path(defra_id),
            Json(AlertAckBody::default()),
        )
        .await;
        assert!(
            matches!(r, Err((StatusCode::NOT_FOUND, _))),
            "cross-site ack must 404: {r:?}"
        );
        // Platform-wide (NULL) alert → permitted (the feed shows it to scoped users).
        let r = events_alert_ack(
            AuthExtractor(scoped()),
            Path(global_id),
            Json(AlertAckBody::default()),
        )
        .await;
        assert!(
            r.is_ok(),
            "platform-wide ack must succeed for a scoped principal: {r:?}"
        );

        for id in [defra_id, global_id] {
            sqlx::query("DELETE FROM alert_acks WHERE event_id = $1")
                .bind(id)
                .execute(pool)
                .await
                .ok();
        }
    }

    /// #8: degradation status reads from the DB (migration 025 seed), not the
    /// in-memory engine — so it survives restart. The component_status rows fold
    /// into AdapterComponentStatus correctly. Non-mutating.
    #[tokio::test]
    async fn degradation_list_reflects_seeded_db_state() {
        use ryuki_engine::degradation_mode::{ComponentStatus, SiteDegradationState};
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let sites = crate::repos::degradation::list_site_statuses(pool)
            .await
            .expect("list site statuses");
        let find = |s: &str| sites.iter().find(|x| x.site == s).cloned();
        let defra = find("DEFRA").expect("DEFRA seeded");
        assert_eq!(defra.state, SiteDegradationState::Healthy);
        let gblon = find("GBLON").expect("GBLON seeded");
        assert_eq!(gblon.state, SiteDegradationState::Degraded);
        // GBLON's hyperv + veeam adapters are seeded degraded → mapped into the struct.
        assert_eq!(gblon.adapter_status.hyperv, ComponentStatus::Degraded);
        assert_eq!(gblon.adapter_status.veeam, ComponentStatus::Degraded);
        assert_eq!(gblon.adapter_status.vmware, ComponentStatus::Up);
    }

