    /// Every one of the 14 request types round-trips create -> read with its
    /// REAL persisted payload (not a fabricated VM shape). ServerDeployment
    /// carries cpu/memory; the other 13 carry the common envelope.
    #[tokio::test]
    async fn test_all_request_types_persist_real_payload() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let session = admin_session("requester-p2");

        let types = [
            "server-deployment",
            "patch-maintenance",
            "reboot-orchestration",
            "controlled-restore",
            "zabbix-onboarding",
            "cmdb-import",
            "cmdb-update-export",
            "operator-runbook-launch",
            "application-environment-retirement",
            "vm-decommission-quarantine",
            "request-preflight",
            "vm-day2-change",
            "snapshot-governance",
            "backup-coverage-report",
        ];

        for rt in types {
            let body = create_body(rt);
            let Ok(Json(created)) =
                requests_create(AuthExtractor(session.clone()), Json(body)).await
            else {
                panic!("create must succeed for {rt}");
            };
            let id = Uuid::parse_str(created["id"].as_str().expect("id")).expect("uuid");

            let row = read_global_row(pool, id).await;
            // requester/owner anchored to the verified principal, not the name.
            assert_eq!(row.requester.as_deref(), Some("requester-p2"), "{rt}");
            assert_eq!(row.owner.as_deref(), Some("requester-p2"), "{rt}");
            assert_eq!(row.criticality, "standard", "{rt}");
            // The intake stage is REAL persisted history, not fabricated.
            let stages: Vec<ryuki_engine::models::Stage> =
                serde_json::from_value(row.stages.clone()).expect("stages");
            assert!(
                stages.iter().any(|s| s.name == "intake"
                    && s.status == ryuki_engine::models::StageStatus::Completed),
                "{rt}: intake stage must be persisted"
            );
            // Payload is authoritative and type-shaped.
            assert_eq!(row.payload["request_type"], json!(rt), "{rt}");
            assert_eq!(row.payload["site"], json!("DEFRA"), "{rt}");
            if rt == "server-deployment" {
                assert_eq!(row.payload["cpu"], json!(4), "{rt} carries cpu");
                assert_eq!(row.payload["memory_gb"], json!(8), "{rt} carries memory");
            } else {
                // The other 13 are intake-thin: the common envelope, no VM keys.
                assert!(
                    row.payload.get("cpu").is_none(),
                    "{rt} has no cpu in payload"
                );
            }
            // plan/validation_results stay null at intake.
            assert_eq!(row.plan, Value::Null, "{rt} plan null at intake");
            assert_eq!(
                row.validation_results,
                Value::Null,
                "{rt} validation null at intake"
            );

            cleanup_request(pool, id).await;
        }
    }

    /// Drive a request create -> validate -> plan -> approve -> lock -> execute
    /// -> verify and assert the durable stages/approval_route/plan PERSISTED and
    /// rehydrate FAITHFULLY — no fabricated DRY-RUN string, real stage history —
    /// across a fresh hydration (simulating a restart by re-reading the row).
    #[tokio::test]
    async fn test_full_lifecycle_persists_and_rehydrates_real_state() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let session = admin_session("approver-p2");

        let Ok(Json(created)) = requests_create(
            AuthExtractor(session.clone()),
            Json(create_body("server-deployment")),
        )
        .await
        else {
            panic!("create must succeed");
        };
        let id_str = created["id"].as_str().expect("id").to_string();
        let id = Uuid::parse_str(&id_str).expect("uuid");

        // Drive the lifecycle through the handlers (each commits durably).
        let p = |s: &str| Path(s.to_string());
        let _ = requests_validate(p(&id_str), AuthExtractor(session.clone()))
            .await
            .expect("validate");
        let _ = requests_plan(p(&id_str), AuthExtractor(session.clone()))
            .await
            .expect("plan");
        let _ = requests_approve(p(&id_str), AuthExtractor(session.clone()))
            .await
            .expect("approve");
        let _ = requests_lock(p(&id_str), AuthExtractor(session.clone()))
            .await
            .expect("lock");
        // Execute now DISPATCHES an OfflineDryRun agent_job (AWX-style) instead
        // of simulating completion in-process. The request sits in Executing
        // with the execute stage In-Progress until an execution agent posts its
        // signed result (the result -> request backlink, a later slice, drives
        // Executing -> Verifying -> Completed).
        let Json(dispatch) = requests_execute(
            p(&id_str),
            Query(ExecuteParams::default()),
            AuthExtractor(session.clone()),
        )
        .await
        .expect("execute dispatch");
        assert_eq!(dispatch["status"].as_str(), Some("executing"));
        let job_id = dispatch["agent_job_id"]
            .as_str()
            .expect("agent_job_id in dispatch response");
        uuid::Uuid::parse_str(job_id).expect("agent_job_id is a uuid");

        // Simulate a RESTART: re-read the persisted row and hydrate fresh — this
        // is exactly what a cold-started API does. No in-memory state.
        let row = read_global_row(pool, id).await;
        assert_eq!(
            row.status, "executing",
            "request is dispatched (Executing), awaiting the agent result"
        );

        // A durable agent_job was enqueued for this request in the same tx.
        let job_count: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM agent_jobs WHERE request_id = $1 AND mode = 'OfflineDryRun'",
        )
        .bind(id)
        .fetch_one(pool)
        .await
        .expect("count agent_jobs");
        assert_eq!(
            job_count, 1,
            "exactly one OfflineDryRun job dispatched for the request"
        );

        // Slice 3: the execution-job endpoint surfaces the dispatched job (the
        // AWX-style "job" view the portal renders).
        let Json(exec_job) =
            requests_execution_job(AuthExtractor(AuthSession::static_dry_run()), p(&id_str))
                .await
                .expect("execution-job endpoint");
        assert_eq!(exec_job["agent_job_id"].as_str(), Some(job_id));
        assert_eq!(exec_job["mode"].as_str(), Some("OfflineDryRun"));
        assert_eq!(exec_job["status"].as_str(), Some("Pending"));
        // Unknown request -> 404.
        let Err((st, _)) = requests_execution_job(
            AuthExtractor(AuthSession::static_dry_run()),
            Path(Uuid::new_v4().to_string()),
        )
        .await
        else {
            panic!("expected 404 for unknown request");
        };
        assert_eq!(st, StatusCode::NOT_FOUND);

        let rehydrated = db_row_to_request(&row, &id_str);
        let stage_names: Vec<&str> = rehydrated.stages.iter().map(|s| s.name.as_str()).collect();
        // REAL persisted history: the engine's plan_request rebuilds the full
        // stage list and each transition appends its own stage, so the
        // cumulative history rehydrates faithfully through execute (In-Progress).
        for expected in ["validate", "plan", "approve", "lock", "execute"] {
            assert!(
                stage_names.contains(&expected),
                "rehydrated stages must include {expected}; got {stage_names:?}"
            );
        }

        // The plan column holds the REAL plan stages, NOT a fabricated string.
        assert_ne!(row.plan, Value::Null, "plan persisted");
        let plan_stages: Vec<ryuki_engine::models::Stage> =
            serde_json::from_value(row.plan.clone()).expect("plan deserializes as Vec<Stage>");
        assert!(
            plan_stages.iter().any(|s| s.name == "plan"),
            "persisted plan carries the plan stage"
        );

        // validation_results persisted (passed).
        let validation: ryuki_engine::models::ValidationResult =
            serde_json::from_value(row.validation_results.clone())
                .expect("validation_results deserializes");
        assert!(validation.passed, "validation result persisted as passed");

        // approval_route persisted with the verified approver.
        assert!(
            rehydrated
                .approval_route
                .contains(&"approver-p2".to_string()),
            "approval_route persisted; got {:?}",
            rehydrated.approval_route
        );

        // requester is the verified principal, NOT the request name.
        assert_eq!(rehydrated.requester, "approver-p2");
        assert_ne!(rehydrated.requester, row.name);

        // No fabricated DRY-RUN reconstruction string leaks into any plan stage
        // metadata key the old fabrication used.
        let fabricated = rehydrated.stages.iter().any(|s| {
            s.metadata.get("dry_run").map(String::as_str) == Some("true")
                && s.name == "validate"
                && s.evidence.is_empty()
                && s.started_at.is_none()
        });
        assert!(
            !fabricated,
            "no fabricated validate stage (None timestamps + empty evidence) may appear"
        );

        cleanup_request(pool, id).await;
    }

    /// Theme 8: the post-completion Protect -> Publish stages persist durably and
    /// advance the request Completed -> Protecting -> Operational, with the
    /// protect/publish stages rehydrating from the JSONB column.
    #[tokio::test]
    async fn test_protect_publish_persists_post_completion() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let session = admin_session("approver-pp");
        let p = |s: &str| Path(s.to_string());

        let Ok(Json(created)) = requests_create(
            AuthExtractor(session.clone()),
            Json(create_body("server-deployment")),
        )
        .await
        else {
            panic!("create must succeed");
        };
        let id_str = created["id"].as_str().expect("id").to_string();
        let id = Uuid::parse_str(&id_str).expect("uuid");

        let _ = requests_validate(p(&id_str), AuthExtractor(session.clone()))
            .await
            .expect("validate");
        let _ = requests_plan(p(&id_str), AuthExtractor(session.clone()))
            .await
            .expect("plan");
        let _ = requests_approve(p(&id_str), AuthExtractor(session.clone()))
            .await
            .expect("approve");
        let _ = requests_lock(p(&id_str), AuthExtractor(session.clone()))
            .await
            .expect("lock");

        // Execute dispatches an async agent job (the request sits in Executing
        // until the agent-result backlink — a separate slice — drives it to
        // Completed). Protect requires Completed, so force the row to Completed
        // with a finished verify stage, standing in for that backlink.
        let row = read_global_row(pool, id).await;
        let mut req = db_row_to_request(&row, &id_str);
        req.status = ryuki_engine::models::RequestStatus::Completed;
        // A faithful Completed row has the execute + verify stages finished (the
        // real path: agent-result backlink completes execute, then requests_verify
        // completes verify and lands Completed).
        req.stages.push(completed_request_stage("execute", vec![]));
        req.stages.push(completed_request_stage("verify", vec![]));
        let stages_json = serde_json::to_value(&req.stages).unwrap_or_else(|_| json!([]));
        sqlx::query(
            "UPDATE requests SET status = 'completed', stage = 'verify', stages = $2::jsonb WHERE id = $1",
        )
        .bind(id)
        .bind(&stages_json)
        .execute(pool)
        .await
        .expect("force completed state");

        // Protect: Completed -> Protecting with backup-coverage evidence.
        let Json(protect_ev) = requests_protect(p(&id_str), AuthExtractor(session.clone()))
            .await
            .expect("protect must succeed from Completed");
        assert!(
            protect_ev
                .as_array()
                .map(|a| a.iter().any(|e| e["key"] == "protection-policy-summary"))
                .unwrap_or(false),
            "protect returns the backup-coverage evidence"
        );
        let row = read_global_row(pool, id).await;
        assert_eq!(
            row.status, "protecting",
            "request is Protecting after protect"
        );

        // Publish: Protecting -> Operational with CMDB evidence.
        let Json(publish_ev) = requests_publish(p(&id_str), AuthExtractor(session.clone()))
            .await
            .expect("publish must succeed from Protecting");
        assert!(
            publish_ev
                .as_array()
                .map(|a| a.iter().any(|e| e["key"] == "publish-plan"))
                .unwrap_or(false),
            "publish returns the CMDB publish-plan evidence"
        );
        let row = read_global_row(pool, id).await;
        assert_eq!(
            row.status, "operational",
            "request rests in Operational after publish"
        );

        // The protect + publish stages rehydrate from the persisted JSONB.
        let rehydrated = db_row_to_request(&row, &id_str);
        let names: Vec<&str> = rehydrated.stages.iter().map(|s| s.name.as_str()).collect();
        assert!(
            names.contains(&"protect") && names.contains(&"publish"),
            "post-completion stages persisted; got {names:?}"
        );

        // From Operational, publish is no longer valid (engine guard -> 400).
        let Err((st, _)) = requests_publish(p(&id_str), AuthExtractor(session.clone())).await
        else {
            panic!("publish from Operational must be refused");
        };
        assert!(
            st == StatusCode::BAD_REQUEST || st == StatusCode::CONFLICT,
            "re-publish rejected; got {st}"
        );

        // Retire: Operational -> Retired with decommission-plan evidence.
        let Json(retire_ev) = requests_retire(p(&id_str), AuthExtractor(session.clone()))
            .await
            .expect("retire must succeed from Operational");
        assert!(
            retire_ev
                .as_array()
                .map(|a| a.iter().any(|e| e["key"] == "retirement-plan"))
                .unwrap_or(false),
            "retire returns the decommission retirement-plan evidence"
        );
        let row = read_global_row(pool, id).await;
        assert_eq!(row.status, "retired", "request is Retired after retire");
        let rehydrated = db_row_to_request(&row, &id_str);
        let names: Vec<&str> = rehydrated.stages.iter().map(|s| s.name.as_str()).collect();
        assert!(
            names.contains(&"retire"),
            "retire stage persisted; got {names:?}"
        );

        // From Retired (terminal), retire is no longer valid (engine guard -> 400).
        let Err((st, _)) = requests_retire(p(&id_str), AuthExtractor(session.clone())).await else {
            panic!("retire from Retired must be refused");
        };
        assert!(
            st == StatusCode::BAD_REQUEST || st == StatusCode::CONFLICT,
            "re-retire rejected; got {st}"
        );

        cleanup_request(pool, id).await;
    }

    /// AWX bridge slice 5a: an admin can dispatch a LivePlan job (a real
    /// terraform plan / ansible --check against a backend — no mutation);
    /// live-apply is refused via execute (it requires a CP-signed grant).
    #[tokio::test]
    async fn test_execute_live_plan_dispatch_and_live_apply_refused() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        let session = admin_session("approver-lp");
        let p = |s: &str| Path(s.to_string());

        // live-apply is never dispatchable via execute -> 400 (mode resolution
        // happens before the request is even loaded).
        let Err((st, _)) = requests_execute(
            p("any-id"),
            Query(ExecuteParams {
                mode: Some("live-apply".into()),
            }),
            AuthExtractor(session.clone()),
        )
        .await
        else {
            panic!("live-apply must be refused via execute");
        };
        assert_eq!(st, StatusCode::BAD_REQUEST);

        // Drive a request to Locked, then dispatch a LivePlan as admin.
        let Ok(Json(created)) = requests_create(
            AuthExtractor(session.clone()),
            Json(create_body("server-deployment")),
        )
        .await
        else {
            panic!("create must succeed");
        };
        let id_str = created["id"].as_str().expect("id").to_string();
        let id = Uuid::parse_str(&id_str).expect("uuid");
        let _ = requests_validate(p(&id_str), AuthExtractor(session.clone()))
            .await
            .expect("validate");
        let _ = requests_plan(p(&id_str), AuthExtractor(session.clone()))
            .await
            .expect("plan");
        let _ = requests_approve(p(&id_str), AuthExtractor(session.clone()))
            .await
            .expect("approve");
        let _ = requests_lock(p(&id_str), AuthExtractor(session.clone()))
            .await
            .expect("lock");

        let Json(dispatch) = requests_execute(
            p(&id_str),
            Query(ExecuteParams {
                mode: Some("live-plan".into()),
            }),
            AuthExtractor(session.clone()),
        )
        .await
        .expect("live-plan dispatch");
        assert_eq!(dispatch["mode"].as_str(), Some("LivePlan"));

        let job_mode: String = sqlx::query_scalar(
            "SELECT mode FROM agent_jobs WHERE request_id = $1 ORDER BY created_at DESC LIMIT 1",
        )
        .bind(id)
        .fetch_one(pool)
        .await
        .expect("job mode");
        assert_eq!(job_mode, "LivePlan", "a LivePlan agent_job was dispatched");

        cleanup_request(pool, id).await;
    }

    /// #2 RBAC: requests_approve_live_apply is admin-tier, but admin does NOT imply
    /// unrestricted scope — a site-scoped admin must not mint a live-apply grant for
    /// another site's request. An out-of-scope request 404s BEFORE any 409 branch
    /// (no existence oracle); the in-scope admin reaches the 409 (no completed plan).
    #[tokio::test]
    async fn approve_live_apply_is_site_scoped() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        // Unrestricted admin creates a DEFRA/production request (create_body site).
        let admin = admin_session("la-scope-admin");
        let p = |s: &str| Path(s.to_string());
        let Ok(Json(created)) = requests_create(
            AuthExtractor(admin.clone()),
            Json(create_body("server-deployment")),
        )
        .await
        else {
            panic!("create must succeed");
        };
        let id_str = created["id"].as_str().expect("id").to_string();
        let id = Uuid::parse_str(&id_str).expect("uuid");

        // A GBLON-scoped admin must 404 (not 409) — scope guard precedes the
        // no-completed-plan 409, so it is not an existence oracle.
        let mut gblon_admin = admin.clone();
        gblon_admin.site_scope = vec!["GBLON".into()];
        let scoped = requests_approve_live_apply(p(&id_str), AuthExtractor(gblon_admin)).await;
        assert!(
            matches!(scoped, Err((StatusCode::NOT_FOUND, _))),
            "an out-of-scope admin must 404, not 409: {scoped:?}"
        );

        // The in-scope (unrestricted) admin reaches the 409 (no completed plan yet),
        // proving the request itself is reachable for the right scope.
        let reachable = requests_approve_live_apply(p(&id_str), AuthExtractor(admin.clone())).await;
        assert!(
            matches!(reachable, Err((StatusCode::CONFLICT, _))),
            "in-scope admin must reach the no-plan 409: {reachable:?}"
        );

        cleanup_request(pool, id).await;
    }

    /// AWX bridge slice 5c: an admin approves a request's completed LivePlan,
    /// minting a CP-signed LiveApply job reconstructed from that plan. No
    /// completed plan -> 409; non-admin -> 403.
    #[tokio::test]
    async fn test_approve_live_apply_mints_grant_from_completed_plan() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };
        // Idempotent test init of the process-global CP signing key.
        crate::cp_identity::init_cp_key_for_test(ed25519_dalek::SigningKey::from_bytes(&[7u8; 32]));
        let admin = admin_session("approver-la");
        let p = |s: &str| Path(s.to_string());

        let Ok(Json(created)) = requests_create(
            AuthExtractor(admin.clone()),
            Json(create_body("server-deployment")),
        )
        .await
        else {
            panic!("create must succeed");
        };
        let id_str = created["id"].as_str().expect("id").to_string();
        let id = Uuid::parse_str(&id_str).expect("uuid");

        // No completed live plan yet -> 409.
        let Err((st, _)) =
            requests_approve_live_apply(p(&id_str), AuthExtractor(admin.clone())).await
        else {
            panic!("expected 409 without a completed live plan");
        };
        assert_eq!(st, StatusCode::CONFLICT);

        // Seed a SUCCEEDED LivePlan job: spec.request_id == uid, mode serializes
        // snake_case ("live_plan"), 64-hex evidence digest (the plan digest).
        let digest = "a".repeat(64);
        let spec = json!({
            "request_id": id_str,
            "offering_id": Uuid::new_v4().to_string(),
            "iac_ref": "linux-server-deployment@v1",
            "iac_digest": "0".repeat(64),
            "vars": {},
            "mode": "live_plan"
        });
        sqlx::query(
            "INSERT INTO agent_jobs \
             (request_id, platform, spec, mode, status, result_status, evidence_digest, completed_at) \
             VALUES ($1, 'DEFRA', $2::jsonb, 'LivePlan', 'Succeeded', 'planned', $3, NOW())",
        )
        .bind(id)
        .bind(&spec)
        .bind(&digest)
        .execute(pool)
        .await
        .expect("seed LivePlan job");

        // Admin approve -> mints exactly one LiveApply job (signed grant).
        let _ = requests_approve_live_apply(p(&id_str), AuthExtractor(admin.clone()))
            .await
            .expect("approve-live-apply");
        let la_count: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM agent_jobs WHERE request_id = $1 AND mode = 'LiveApply'",
        )
        .bind(id)
        .fetch_one(pool)
        .await
        .expect("count LiveApply");
        assert_eq!(
            la_count, 1,
            "a LiveApply job was minted from the approved plan"
        );

        // Idempotency: a second approve while a LiveApply is active -> 409, and
        // NO second job is minted (no double-apply).
        let Err((st_dup, _)) =
            requests_approve_live_apply(p(&id_str), AuthExtractor(admin.clone())).await
        else {
            panic!("expected 409 — a live-apply is already active");
        };
        assert_eq!(st_dup, StatusCode::CONFLICT);
        let la_count2: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM agent_jobs WHERE request_id = $1 AND mode = 'LiveApply'",
        )
        .bind(id)
        .fetch_one(pool)
        .await
        .expect("count LiveApply after dup");
        assert_eq!(la_count2, 1, "no second LiveApply job is minted on retry");

        sqlx::query("DELETE FROM agent_jobs WHERE request_id = $1")
            .bind(id)
            .execute(pool)
            .await
            .ok();
        cleanup_request(pool, id).await;
    }

